quests[12391] = { id = 12391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
