quests[12410] = { id = 12410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[12411] = { id = 12411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sister's Pledge", description = "Please, {name}.  I know it is Arugal you're after.  I swear on my father's memory I will help you take him down.\n\nBut I must beg you... Anya is completely innocent, we cannot leave her with these savages.\n\nHelp me rescue my sister and you'll have me at your side when you face Arugal.\n\nI know the den Anatoly spoke of.  We'll find it on the other side of this hill.  Let's go, my sister's in danger.", sourceObjective = "Look for Anya in the Duskhowl Den near Solstice Village.", completion = "I don't want to be here anymore.  The worgen-men are mean.", sourceObjectiveStatus = "unverified-source-field" }
quests[12412] = { id = 12412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Enemy's Friend", description = "If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills.\n\nThere is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here.\n\nSo far we've been successful... but there's something that could tip the scales in our enemy's favor.\n\nFar to the east  of here, at the Forest Edge's Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.", sourceObjective = "Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest's Edge Post.", progress = "Did you complete your task?  If not, what are you doing here?", completion = "You're back.  And you're alive.\n\nNow what's this nonsense about worgen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12413] = { id = 12413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Silverbrook", description = "A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance's.\n\nNow they've become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.", sourceObjective = "Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.", completion = "Not bad, {name}.  You might be slightly more useful than I initially thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[12414] = { id = 12414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mounting Up", description = "Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay.\n\nWe chose a good place to put the camp 'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap'n put me in charge of capturing some of 'em.\n\nWill you help? I've got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.", sourceObjective = "Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment.", progress = "Did you get all the mustangs we'll need?", completion = "Wow! These sure are good horses! I think the Cap'n will be real pleased with our work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12415] = { id = 12415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horse Hollerer", description = "The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry.\n\nThey're now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they're able to replace their lost mounts. Take this and throw it near the horses to drive them away.", sourceObjective = "Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah.", completion = "<Soulok nods in approval.>\n\nWell done, {name}. We must not let the Alliance gain any kind of advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12416] = { id = 12416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", sourceObjective = "Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Ceristrasz once you have finished this task.", progress = "I'm glad you're still with us, {race}.", completion = "It is a disgusting task, but I thank you dearly for doing it.\n\nThe Scourge cannot be permitted to push any further towards Wyrmrest or we are sure to lose it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12417] = { id = 12417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", sourceObjective = "Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Ceristrasz once the task is complete.", progress = "I started to worry that the Scourge in the shrine had claimed you. It is good that you yet live.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12418] = { id = 12418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", sourceObjective = "Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.", progress = "You've returned! Have you done as I've asked of you?", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, {race}. I will send word to the council of what your kind have accomplished here. Go with our blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[12419] = { id = 12419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Ruby Dragonshrine", description = "As you pick up the brooch, its faint glow brightens slightly.\n\nKrasus will want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.", sourceObjective = "Bring Dahlia Suntouch's Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia's fate.", progress = "Hello, {race}. I sense the presence of my Ruby Brooch. Hand it here.\n\nWhat has become of Dahlia?", completion = "Dahlia was taken by the Scourge? This is a sad day for all of us.\n\nI will look to finding a new keeper once the shrine is retaken. Thank you for your efforts... the Ruby Dragonshrine is a sacred place to us, and the sacrifices your kind have made will not be easily forgotten.\n\nIt is good to know there are still heroes such as you - I will call upon you one day. Until that day comes, may your adventures be fruitful.", sourceObjectiveStatus = "unverified-source-field" }
quests[12420] = { id = 12420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, {name}!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving.", sourceObjectiveStatus = "unverified-source-field" }
quests[12421] = { id = 12421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Ray'ma Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, {name}?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like.", sourceObjectiveStatus = "unverified-source-field" }
quests[12422] = { id = 12422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Clemency", description = "Listen, {name}.  I need you to act with discretion and speed.\n\nOne of Krenna's top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.\n\nWe can't let that happen.  You see, the prisoner matches the description of Mikhail's older daughter in his diary.\n\nIf we set her loose and follow her closely, she'll lead us to whoever's controlling the trappers.  Take this letter to her.", sourceObjective = "Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills.", progress = "Are you here to kill me?", completion = "You're going to let me go... just like that?  Listen, I don't want any trouble with you... these monsters killed my father and took my sister.  I have other things on my mind right now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12423] = { id = 12423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikhail's Journal", description = "From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail.\n\nIt is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.", sourceObjective = "Bring Mikhail's Journal to Conqueror Krenna in Conquest Hold.", progress = "What's that you've got there?", completion = "Hah!  Is this some sort of joke?\n\nI barely have any use for books I can actually understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[12424] = { id = 12424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgonna", description = "This book is written in the pig-tongue the humans use.  It needs to be burned immediately.\n\nHand it to my sister Gorgonna and do not waste my time.", sourceObjective = "Bring Mikhail's Journal to Gorgonna in Conquest Hold.", progress = "You have something to show me?", completion = "Could it be?  The man who wrote this journal feared for his daughters' lives so he sent them away from Silverbrook.\n\nWe just captured an outcast in the outskirts of town about the same age as the eldest daughter.\n\nListen, {name}.  There's more happening here than meets the eye... we can't just burn this diary.", sourceObjectiveStatus = "unverified-source-field" }
quests[12425] = { id = 12425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna the Blind", description = "This trapper business has the potential to be more important than we've accounted for.\n\nIf they're not with the Alliance, there's a good chance they're with the Scourge, which could mean trouble.\n\nOur previous efforts might've paid off, though.  We spotted our former captive meeting with a fortune teller of some sort before we lost track of her.\n\nI'm almost certain now that she will take us to their leader if we can find her again.  Find Ruuna the Blind and see what you can find out.", sourceObjective = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking.", sourceObjectiveStatus = "unverified-source-field" }
quests[12427] = { id = 12427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Bear Wrestling!", description = "So you're interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition.\n\nNice loophole, eh?\n\nAnyway, if you're interested I can start you off with something easy, a measly bear.  I'll even let you bring friends along!", sourceObjective = "Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", progress = "It's not over until you or the bear tips over, friend!", completion = "Nice work, mon!  Here's your cut.", sourceObjectiveStatus = "unverified-source-field" }
quests[12428] = { id = 12428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Mad Furbolg Fighting", description = "You're not bad.  Not bad at all.\n\nThink you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs?\n\nGood, good.  Get your crew together, and head to the ring.  Let's give these folks a show... maybe we can earn some more coin while we're at it.", sourceObjective = "Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", completion = "Those were some sharp moves, friend!  Lots of bets against you, which is good news cash-wise!", sourceObjectiveStatus = "unverified-source-field" }
quests[12429] = { id = 12429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Blood and Metal", description = "It's nice to have a real fighter around these parts... we'd only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know?\n\nAnyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?", sourceObjective = "Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", completion = "My heart nearly skipped a beat there!  Thought that mound of metal was gonna get ya, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12430] = { id = 12430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Death Is Likely", description = "I'm gonna shoot straight with ya, kid.  This next contender's a murderer.\n\nLiterally.\n\nHe was to be executed last week, but he strangled the hangman with his left hand, so Krenna's guards sort of let me have him.\n\nFeel free to pass on this one.  I wouldn't blame ya.", sourceObjective = "Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", progress = "It's not over until... well, you know the drift by now.", completion = "Fancy footwork, fancy footwork.  You really made quick work of that crazy orc, friend.\n\nOdds were against you seven-to-one; made some nice coin on that one!", sourceObjectiveStatus = "unverified-source-field" }
quests[12431] = { id = 12431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Final Showdown", description = "You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately.\n\nThere are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture!\n\nAt any rate, you can't run away from fate... best get in there on the quick and get it over with.", sourceObjective = "Defeat Krenna in the Conquest Pit.", progress = "It is good to see you, {name}.", completion = "What happened today... had to happen.  It doesn't mean I have to be happy about it.\n\nI've freed my people from a tyrant, but I've also lost a sister.  I thank you for your help, {name}.  I wish to be alone now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12432] = { id = 12432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Red Rocket", description = "You there, {race}! Get your lousy carcass over here!\n\nThe Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there's only one thing to do - destroy it!\n\nThe goblin at the end of the dock here has some torpedoes all ready to go. He's got all the fuel for them on the docked goblin ship to the north.\n\nGet some fuel, then commandeer one of the torpedoes and ride it into their ship.\n\nDismissed!", sourceObjective = "General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat.\n\nGeneral Gorlok will only be present at the lighthouse when the Horde has it in their possession.", progress = "Has that Alliance lumber been burned yet, {class}?", completion = "Ha hah! What a ride, eh {class}?\n\nIf we can't control the resources here, then no one can!\n\nWhen will those puny Alliance pests realize that they are no match for the might of the Horde?", sourceObjectiveStatus = "unverified-source-field" }
quests[12433] = { id = 12433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", sourceObjective = "Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.", progress = "You got some of that element 115, {name}?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find.", sourceObjectiveStatus = "unverified-source-field" }
quests[12434] = { id = 12434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Always Seeking Solvent", progress = "Got some more of that element 115 for me, {name}?", completion = "Nice work, friend!\n\nKeep 'em comin'." }
quests[12435] = { id = 12435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Lord Devrestrasz", description = "I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple!\n\nI have appointed Lord Devrestrasz as the commander of Wyrmrest's defenses.\n\nSpeak with Torastrasza to ride a drake down to him.\n\nPlease lend him your aid, {name}. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.", sourceObjective = "Speak with Lord Devrestrasz at Wyrmrest Temple.", completion = "You must be {name}. The queen informed me that you would be coming.\n\nIf you are willing, we are in great need of your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12436] = { id = 12436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplemental Income", description = "Hail, {class}.  You'll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell.\n\nAll this is stifling business.  I'm hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don't you go hunt down some stag and bring me the venison?\n\nThey're numerous in the area, so bring me only the best meat.", sourceObjective = "Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag.", progress = "You get that venison yet, {name}?", completion = "Nice job, {name}.  These will feed two or three grunts each.  Not bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[12437] = { id = 12437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Red Rocket", description = "Listen, {name}. This battle is as much over resources as tactical supremacy.\n\nI have a mission that could turn the tide in our struggle against the Horde here.\n\nThere are torpedoes at the end of the dock that we can use to take down the Horde's lumber ship to the northwest.\n\nYou'll need to get some of the fuel that's stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!", sourceObjective = "Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment.\n\nCommander Howser will only be present at the lighthouse when the Alliance has it in their possession.", progress = "Has that Horde lumber ship been burned yet, {name}?", completion = "Good to see that you survived that impact. Quite the explosion!\n\nWe can't afford for the Horde to make off with all that lumber.\n\nWell done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12438] = { id = 12438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Kreug Oathbreaker", description = "Posted by: Illusia Lune\n\nThe Scourge flesh giant known as Kreug Oathbreaker was responsible for the deaths of my husband, children and my dear friends, the Whisperveils. Those brave enough to take on this bounty will find Kreug in the southeastern reaches of the Carrion Fields.\n\nI demand justice! Kill Kreug Oathbreaker!\n\nIn the event that Kreug is slain, I have pooled money and items together and given them to Highlord Leoric Von Zeldig to give out as a reward.\n\nPlease vindicate us!", sourceObjective = "Kill Kreug Oathbreaker and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", completion = "Well done, {name}. I will notify Illusia that a hero has heard her call for help and risen to meet the challenge! Here is your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[12439] = { id = 12439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbance In The West", description = "Another force threatens to destroy all that we have worked for, {name}. You must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately!\n\nGo now, {name}! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars' Rest. Speak with Archmage Modera when you arrive.", sourceObjective = "Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars' Rest in western Dragonblight.", completion = "We definitely don't want another sundering, friend. I'll do all that I can to help you on your mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[12440] = { id = 12440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stars' Rest!", description = "When you are ready I will place you on my fastest gryphon to Stars' Rest. Once you get there, find and speak with Archmage Modera.\n\nGood luck, ally!", sourceObjective = "Speak with the Image of Archmage Modera at Stars' Rest in western Dragonblight.", completion = "Vas heard my distress call then, eh? Not a moment too soon, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[12441] = { id = 12441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: High Shaman Bloodpaw", description = "Posted by: Drolfy\n\nWhile out in the Eldritch Heights with my cousins, Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We attempted to flee, but I fear they got Skrotee and Brote.\n\nI demand retribution! Is there someone brave enough to venture to the southeastern reaches of Dragonblight, to the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies?\n\nI have given a hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this bounty!", sourceObjective = "Kill High Shaman Bloodpaw and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", progress = "Have you faced Bloodpaw?", completion = "Outstanding work, {name}! I will notify Drolfy that a hero did rise to meet his challenge and that the cruel Bloodpaw is no more!", sourceObjectiveStatus = "unverified-source-field" }
quests[12442] = { id = 12442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Onslaught Commander Iustus", description = "Posted by: Highlord Leoric Von Zeldig\n\nUpon the northeastern path from Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated actions must be met with force!\n\nWintergarde demands justice! Seek out Onslaught Commander Iustus at Onslaught Base Camp to the northeast and end his miserable existence.\n\nI will hand out the reward for this bounty to any who would dare take up the task!", sourceObjective = "Kill Onslaught Commander Iustus and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", completion = "At least for now the Scarlet Onslaught suffers a setback in their nefarious plans. You have done Wintergarde a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12443] = { id = 12443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", sourceObjective = "Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.", progress = "You got some of that element 115, {name}?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find.", sourceObjectiveStatus = "unverified-source-field" }
quests[12444] = { id = 12444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Skirmish", description = "The Venture Company's on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them.\n\nTheir abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands on them.\n\nThe Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.", sourceObjective = "Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.", progress = "How's the hunt going?", completion = "Nice work, {name}.  We could use a few more folks like you up here.  We could really show the Horde not to mess with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12446] = { id = 12446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Always Seeking Solvent", progress = "Got some more of that element 115 for me, {name}?", completion = "Nice work, friend!\n\nKeep 'em comin'." }
quests[12447] = { id = 12447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obsidian Dragonshrine", description = "The Scourge come. Korialstrasz calls upon his allies in a futile attempt to save their Ruby Dragonshrine, but it seems the good graces of the red flight don't extend to saving the shrines of the other flights.\n\nSurprised? I'm not.\n\nThere is another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin that now infest it. All it would take to prove yourself more noble and righteous than Alexstrasza herself is a quick jaunt over there and a few swings of a blade.\n\nI'm amused.", sourceObjective = "Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid.", completion = "I'm trying to decide at which I'm more surprised... that you actually came to the aid of a Black Dragon or that you're still in one piece after speaking with Nalice.\n\nHer words drip venom, but I suppose Wyrmrest can keep even our kind in check sometimes.\n\nOr perhaps it's just the armies of the red dragonflight that are massed around her.", sourceObjectiveStatus = "unverified-source-field" }
quests[12448] = { id = 12448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", sourceObjective = "Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Vargastrasz once you have finished this task.", progress = "I'm glad you're still with us, {race}.", completion = "It is a disgusting task, but I thank you for doing it.\n\nThe Scourge cannot be permitted to push any further out of the shrine lest all of these lands be overrun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12449] = { id = 12449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through the pass in the south... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", sourceObjective = "Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Vargastrasz once the task is complete.", progress = "I started to worry that the Scourge in the shrine had claimed you. It is good that you yet live.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12450] = { id = 12450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", sourceObjective = "Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.", progress = "You've returned! Have you done as I've asked of you?", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, {race}. Perhaps not all of the Horde bear the black hearts of their ancestors.  I will send word to the council of what your kind have accomplished here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12451] = { id = 12451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Camp Oneqwah", description = "While we build Conquest Hold, I sent Scout Vor'takh to make contact with our taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost part of Grizzly Hills, beyond Grizzlemaw.\n\nMake the journey there, hear Vor'takh's report and offer your assistance with anything he and the local chieftain may need. Your contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful for the assistance.", sourceObjective = "Speak with Scout Vor'takh at Camp Oneqwah.", completion = "<You offer a short introduction, explaining you were sent by Sergeant Nazgrim.>\n\nAh, so you're something in the way of reinforcements, then. Good.\n\nTormak and his men have need of your blade.", sourceObjectiveStatus = "unverified-source-field" }
quests[12452] = { id = 12452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLD The Fate of the Ruby Dragonshrine", sourceObjective = "Bring Dahlia's Ruby Broach to Ceristrasz and inform him of her fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[12453] = { id = 12453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes Above", description = "I've been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we're looking for ways to find an edge.\n\nThe imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them.\n\nBeing able to see our enemy's movements will grant us the strategic advantage we need.  You'll find abundant eagles in the mountains to the east.", sourceObjective = "Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.", completion = "I thank you, {name}.  Your help is appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[12454] = { id = 12454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cycle of Life", description = "Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it.\n\nRecently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood.\n\nInstead, she told our dragonshrine's defenders to treat those not of the green dragonflight as enemies.\n\nI need you to slay some of the skytalons. The shrine must regain its balance.", sourceObjective = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons.", progress = "The sooner that the emerald skytalons can be dealt with, the sooner the Emerald Dragonshrine can be returned to its natural balance.", completion = "Do not regret the part that you played in the cycle of life. Birth, death, and rebirth are all part of the natural order.", sourceObjectiveStatus = "unverified-source-field" }
quests[12455] = { id = 12455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scattered To The Wind", description = "The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields.\n\nI'm gonna need you to go back up and recover the munitions crates that are scattered all over this damned place.\n\nHurry it up! We can't start this offensive without guns and ammo, <buddy/missy>!", sourceObjective = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions.", progress = "Where are my munitions, fella?", completion = "Just in time! Some of my soldiers got a little overzealous and decided to wade into the crypts directly to the east and west of us. Needless to say, they were quickly overwhelmed by those mindless ghouls. We need to rescue the survivors!", sourceObjectiveStatus = "unverified-source-field" }
quests[12456] = { id = 12456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plume of Alystros", description = "I can feel that the shrine is not completely back in balance. The verdant keeper has been angered by our actions, and I sense that he will not listen to reason.\n\nAlystros is an immense skytalon who perches at the south end of the Emerald Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear that we will have to deal with him.\n\nTake these skytalon molts and place them on the ground where he can see them. He will come. Bring me his plume.", sourceObjective = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to acquire The Plume of Alystros.", progress = "Have you managed to deal with Alystros? Do not be afraid to ask your friends for assistance.\n\nIn fact, given that the verdant keeper is very powerful, I recommend it!", completion = "Do not weep for Alystros. He has dedicated his eternal life to the defense of the Emerald Dragonshrine and will be reborn.\n\nHopefully when he returns to us, he will not be gripped with the confusion of the Emerald Nightmare that seems to have taken hold of The Dreamer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12457] = { id = 12457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chain Gun And You", description = "We've set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence.\n\nNow that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you're on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him!\n\nGet a move on!", sourceObjective = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers.", progress = "Have you rescued our injured soldiers?", completion = "{name}, I haven't seen heroics like that since Silithus!\n\nI'll be sure that each and every one of those soldiers puts in a recommendation to Lord Fordragon that you be promoted!\n\nNow, on to more pressing matters. We've gotten reports back from our scouts that Thel'zan is close.", sourceObjectiveStatus = "unverified-source-field" }
quests[12458] = { id = 12458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Lashers", description = "We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer.\n\nAny unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust.\n\nI want to test a theory, and I want you to be my instrument in doing so, young {race}. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.", sourceObjective = "Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds.", progress = "And just how many seeds have you managed to acquire thus far?", completion = "Even now I can feel the pulse of nature from within these seeds.\n\nWe must put them to good use!", sourceObjectiveStatus = "unverified-source-field" }
quests[12459] = { id = 12459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Which Creates Can Also Destroy", description = "Since we only have three seeds, we must put them to the best possible use.\n\nYour targets are one of the reanimated frost wyrms circling to the north near Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha'kalar far to the northeast.\n\nWhile the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.", sourceObjective = "Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.", progress = "What were the results? Are they destroyed?\n\nI need answers!", completion = "Excellent. Just as I suspected all along. I shall have to attempt to contact Ysera and see if she approves.\n\nIf she can be coaxed from her nightmare, of course.\n\nThank you, {name}. You have been indispensable.", sourceObjectiveStatus = "unverified-source-field" }
quests[12460] = { id = 12460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Ruby Dragonshrine", description = "We need you at the Ruby Dragonshrine.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. The situation seems dire, but this affords us a rare opportunity to establish a valuable alliance.\n\nI secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge east of the shrine and help him in any way that you can.", sourceObjective = "Report to Ceristrasz on the ridge east of the Ruby Dragonshrine, west of Wyrmrest.", completion = "Ambassador Lauriel sent you?\n\nIf you talk to her again, please let her know that we are very appreciative of her aid. We are fighting battles on far too many fronts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12461] = { id = 12461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Ruby Dragonshrine", description = "You are leaving to the Ruby Dragonshrine. This is not a request.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. It is not often we are afforded the opportunity to redeem ourselves for the transgressions of our ancestors.\n\nI have secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush the Scourge beneath your boots!\n\nFor the Horde!", sourceObjective = "Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar's Hammer.", completion = "Ambassador Golluck sent you?\n\nIf you talk to him again, please let him know that we are very appreciative of his aid. We are fighting battles on far too many fronts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12462] = { id = 12462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Off A Piece", description = "Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we've been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies.\n\nGo down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.", sourceObjective = "Yord \"Calamity\" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X'avius, Necrolord Horus, and 15 Naxxramas Scourge.", progress = "Did you break yourself off a piece?", completion = "That oughta buy Ambo a little bit of time to get things situated.", sourceObjectiveStatus = "unverified-source-field" }
quests[12463] = { id = 12463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderbeard Must Be Found!", description = "There's been talk of a tunnel dug by Scourge that connects the embalming chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet to hear back from him. If I were a betting man I'd wager that he's a goner.\n\nI want you to go down those steps and head straight through the embalming chamber and look for Plunderbeard. Dead or alive, he'll have answers.", sourceObjective = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard.", completion = "<You discover a journal on Plunderbeard's corpse.>\n\nEntry One:\n\nThey drag corpses through the tunnel to the embalming room for experimentation. There is an endless supply in this mausoleum. Whatever cannot be reanimated is turned into a bone construct of one kind or another.\n\nEntry Two:\n\nI fear that this lich, Thel'zan, hides a dark secret. Who is he? Was he once... one of us?\n\nEntry Three: I have discovered the location of the lich's phylactery. It is...\n\n<The rest of the pages are torn out.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12464] = { id = 12464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Old Enemy", description = "My old enemy, High General Abbendis, has come to Northrend.\n\nSomehow she survived the attacks upon Tyr's Hand and brought a small force north. They've established New Hearthglen to the south.\n\nWhile they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles.\n\nSo, we'll deprive them of their leadership and go about our business. Bring me her head as proof.", sourceObjective = "Deliver The High General's Head to Commander Eligor Dawnbringer at Wintergarde Keep.", progress = "It is done then?", completion = "An unfortunate, but necessary action that we had to take in dealing with Abbendis. In another lifetime, I think I could have imagined fighting side-by-side with her.\n\n<The commander's voice trails off as he reflects a moment before proceeding.>\n\nI'm a little concerned about this grand admiral you describe. Barean Westwind you say? I can't believe that he's still alive. He must be ancient. We'll have to deal with him later, however.\n\nIn the meantime, I think you've earned a reward and a little R & R.", sourceObjectiveStatus = "unverified-source-field" }
quests[12465] = { id = 12465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderbeard's Journal", description = "Whatever was written on the remaining pages of Plunderbeard's journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard's assailants. They must be the ones who tore the journal apart!\n\nShould you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.", sourceObjective = "Recover Page 4 of Plunderbeard's Journal, Page 5 of Plunderbeard's Journal, Page 6 of Plunderbeard's Journal, and Page 7 of Plunderbeard's Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight.", progress = "I certainly don't feel like a winner...", completion = "<Ambo reads through the recovered journal pages.>\n\nThere's some good news and there's some bad news. Which do you want first?\n\nAh hell, why give you a choice? The good news is that if we can get Thel'zan's phylactery, we can destroy him. The bad news is that the phylactery is on a rather large frostwyrm.", sourceObjectiveStatus = "unverified-source-field" }
quests[12466] = { id = 12466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Icestorm: The 7th Legion Front", description = "You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it'll lead you right into the 7th Legion Front.\n\nOnce there, speak with Legion Commander Tyralion. He'll be expecting you.\n\nAnd {name} - it has been a pleasure. Farewell.", sourceObjective = "Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight.", completion = "Now you know why they call this the Dragon Wastes. Bones of the beasts are strewn about as far as the eye can see.\n\nWe've probably taken down a dozen or more frostwyrms and there's still no end in sight. The Scourge's got fuel for ten-thousand more what with all the bones laying about.\n\n<Tyralion clears his throat.>\n\nI don't mean to bore you with the details, hero. We've got the wyrm you're looking for locked in our sights.", sourceObjectiveStatus = "unverified-source-field" }
quests[12467] = { id = 12467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Icestorm: Thel'zan's Phylactery", description = "Your frostwyrm is out there.\n\n<Tyralion points west.>\n\nAnd it's a big one!\n\nWhen you're ready to fight, go speak with \"Wyrmbait.\" He'll \"fetch\" her. Once Icestorm is close enough we'll chain her to the ground and finish her off! Hopefully, with your help, we'll be able to take her down and get you that phylactery.\n\nOnce you've got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He's been making preparations for the final showdown with Thel'zan.", sourceObjective = "Recover Thel'zan's Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep.", progress = "Have you recovered Thel'zan's phylactery?", completion = "We've lost so many good soldiers to that monster, Thel'zan. I wish I could be there to see you crush his phylactery in front of him and end his existence.", sourceObjectiveStatus = "unverified-source-field" }
quests[12468] = { id = 12468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conqueror's Task", description = "The Horde is a magnificent war machine and you are nothing but a cog.\n\nI am in charge of securing fuel for this machine.  If I fail, the machine fails.\n\nLumber, ore, water... it's all here and we want it.  And so does the Alliance.\n\nBefore we can move against the human scum, we need to solidify our control over the western region.\n\nSpeak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then maybe - if you turn out to not be a complete failure - we'll send you on further tasks.", sourceObjective = "Speak to Sergeant Nazgrim in Conquest Hold.", completion = "So Krenna sent you to me?  She must've not liked you very much, but then again who does she like?\n\nCracking this vrykul outpost is going to be a tough, tough job.", sourceObjectiveStatus = "unverified-source-field" }
quests[12469] = { id = 12469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sender", description = "Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate.\n\nIt appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.", sourceObjective = "Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight.", progress = "Hello there!", completion = "Hah! We lost another one, eh? Those harpies are becoming a real nuisance.\n\nNo matter! There's work to be done. Lend a hand around here, will ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[12470] = { id = 12470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Infinite", description = "A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering.\n\nThe Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information.\n\nYou are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed.\n\nBe warned, the Infinite Dragonflight will try to stop you!", sourceObjective = "Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground.\n\nProtect the hourglass for as long as it lasts and then return to her with whatever information you gain.", progress = "What news do you bring? What happened at the Bronze Dragonshrine?\n\nDid you find out who the leader of the Infinite Dragonflight is?", completion = "You saw Nozdormu? That doesn't make any sense.\n\n<Chromie thinks a moment about what you've said.>\n\nActually, that's great news! We had no idea of where or when the Lord of Time had gone to. We just knew that he had disappeared to deal with very important matters.\n\nSo, even though the leader of the Infinite Dragonflight wasn't revealed, you've discovered that Nozdormu is alive and well, and fighting back against them!\n\nThank you, {name}. I'll be seeing you soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12471] = { id = 12471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruelty of the Kvaldir", description = "I thank you for saving me, {name}.  The kvaldir are animals!\n\nThey made us fight the other prisoners.  It would've been more merciful to just kill us all.\n\nThe youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.", sourceObjective = "Speak to Karuk about the Captured Tuskarr Prisoner.", completion = "I thank you, {name}.  You've shown a great deal of goodwill towards my clan.", sourceObjectiveStatus = "unverified-source-field" }
quests[12472] = { id = 12472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finality", description = "Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that's missing now is you.\n\nTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.\n\nThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, {name}! Lead us to victory!", sourceObjective = "Take Thel'zan's Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight.", progress = "<Yorik lets out a sigh of relief.>\n\nWe thought you might not show up, {name}.", completion = "When you're ready I'll place the phylactery out in front of the gateway and call forth Thel'zan.", sourceObjectiveStatus = "unverified-source-field" }
quests[12473] = { id = 12473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End And A Beginning", description = "Every good story has a beginning and an ending, {name}. While your story is far from over, I'll be damned if it's not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you've done at Wintergarde will be a tale told for years to come.\n\nNow, ally, when you are ready I will use the phylactery to coax Thel'zan out of hiding.\n\nShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.", sourceObjective = "Defeat Thel'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", completion = "Wintergarde is saved because of you, {name}. To think that one man could so swiftly turn the tides of battle is hard for most to comprehend; yet here we are - victorious! You have managed to restore the faith of these people and earned the respect of your commanding officers.\n\n \n\nLord Fordragon has returned to Angrathar to prepare our forces for the destruction of the Wrathgate and has requested that you join him! I couldn't recommend a better soldier for the job, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12474] = { id = 12474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fordragon Hold!", description = "With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, {name}!\n\nTake the north gate out of town and travel north by northwest until you arrive at your destination.\n\nLight protect you!", sourceObjective = "Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon.", completion = "This commendation is only given to those who have gone above and beyond the call of duty in the name of the Alliance. I could count the number of times I've handed this one out on one hand, {name}, and never has anyone been more deserving than you! Congratulations!\n\nNow, let us look upon the Wrathgate. Does it look familiar? It should. That strange ore you found at the Wintergarde Mine is exactly what the Wrathgate is made from. We will find its weakness and expose it for all to see! First, though...", sourceObjectiveStatus = "unverified-source-field" }
quests[12475] = { id = 12475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Secrets Men Hide", description = "After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something.\n\nTo the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us.\n\nRetrieve it!", sourceObjective = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him.", progress = "Have you recovered the Onslaught map?", completion = "A cave? Could it be? There can be no other correlation!", sourceObjectiveStatus = "unverified-source-field" }
quests[12476] = { id = 12476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of the Crusade?", description = "To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, {name}.\n\nGo to Onslaught Base Camp and thin them out.", sourceObjective = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.", completion = "Hopefully the message is now clear to the Onslaught. I hope it was enough of a beating to make them doubt their affiliations.", sourceObjectiveStatus = "unverified-source-field" }
quests[12477] = { id = 12477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Redemption", description = "\"The Path of Redemption,\" ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity.\n\nVenture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of \"The Path of Redemption\" from one of the Onslaught soldiers.", sourceObjective = "Return \"The Path of Redemption\" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", progress = "Did you find a copy?", completion = "<Halford reads the journal.>\n\nAbbendis has gone off the deep end. The Light speaks to her now?\n\nDespite the inane ramblings, this journal gives us a never before seen look into the mind of the Scarlet zealots. This was a great find, {name}. Lord Fordragon will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[12478] = { id = 12478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne Cavern", description = "They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed!\n\nTake this scrying orb and travel north out of town and then northwest towards Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.", sourceObjective = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to use Zelig's Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!", progress = "Have you searched Frostmourne Cavern?", completion = "Muradin lives? Could it be? I must nofity King Bronzebeard at once!\n\nI need to consult the orb. There must be more information - somewhere!", sourceObjectiveStatus = "unverified-source-field" }
quests[12479] = { id = 12479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", sourceObjective = "Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12480] = { id = 12480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.", sourceObjective = "Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12481] = { id = 12481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adding Injury to Insult", description = "The vrykul are being clever about this.  Fortunately I've a trick up my sleeve.\n\nThis leader of theirs, Bjorn, is a real hothead.  We've pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we're not quite sure.\n\nTake this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We'll make sure he doesn't make it out alive.", sourceObjective = "Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell's Ambush and help slay him.", progress = "Assassination work isn't as glamorous as it's made out to be.", completion = "Nice work.  That poor sap never saw it coming.", sourceObjectiveStatus = "unverified-source-field" }
quests[12482] = { id = 12482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Nifflevar", description = "We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance.\n\nHead into town and see if you can put a dent in their numbers.", sourceObjective = "Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds.", progress = "Hail, {name}.", completion = "Excellent work, {name}.  When our forces from Vengeance Landing arrive, we'll be able to take care of any vrykul that are left.", sourceObjectiveStatus = "unverified-source-field" }
quests[12483] = { id = 12483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shimmercap Stew", description = "Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before!\n\nThere be a few ingredients found in these parts that he be needin'. They be in ruins to the southwest and the camp just north o' here.\n\nWhatd'ya say, mon?", sourceObjective = "Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak'Zin Ruins and 5 Sweetroot from Zeb'Halak.", progress = "You get those ingredients for 'ol Prigmon, {name}?", completion = "Oh, mon - shimmercap stew! I can almost taste it already....", sourceObjectiveStatus = "unverified-source-field" }
quests[12484] = { id = 12484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourgekabob", description = "Ugh.\n\nWrappin' up these unfortunate trolls be makin' my heart ache, but not so much as my back!\n\nHelp ol' Prigmon out and haul one of these carcasses over to Mack.\n\nIf we don't burn 'em they be walkin' again in no time.", sourceObjective = "Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire.", progress = "Whatcha got there, {race}?", completion = "Nothin' better than watchin' them shcourge burn... <hic>.\n\nWrote a little shong about it. Wanna hear it? Here goes....", sourceObjectiveStatus = "unverified-source-field" }
quests[12486] = { id = 12486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Bor'gorok Outpost, Quickly!", description = "Did you feel it?\n\n<Sauranok momentarily clutches his chest in confusion. His hand comes away trailing red-hot steam.>\n\nSomething terrible has happened to my old friend, Farseer Grimwalker. I just sensed it.\n\nHe had a pupil that he took with him when he went north. They were going to help the overlord establish an outpost on the edge of Sholazar Basin.\n\nHer name is Snarlfang. She is a spirit talker.\n\nPerhaps she will know what happened. Or, at least, she can help you to find out.", sourceObjective = "Speak with Spirit Talker Snarlfang at Bor'gorok Outpost.", completion = "The mystic knows? You say he felt that something horrible happened to Farseer Grimwalker?\n\nIt is as I feared!", sourceObjectiveStatus = "unverified-source-field" }
quests[12487] = { id = 12487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Conquest Hold, But Be Careful!", description = "I've received a request for help from our base in the Grizzly Hills. I'm sending you to see Conqueror Krenna.\n\n<The high executor waves a sheaf of parchment in the air as if he could care less what is written on it.>\n\nShe's attempting to secure all of the natural resources or somesuch. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nFollow the road east and then southeast. Cross the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.", sourceObjective = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.", completion = "Who are you?\n\nTell me why I shouldn't split you in two where you stand!", sourceObjectiveStatus = "unverified-source-field" }
quests[12488] = { id = 12488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Executor Needs You", description = "It's a good thing that I intercepted this request from High Executor Wroth before it got to Overlord Agmar. What is Wroth thinking?\n\n<The sergeant rips up the letter that he's holding.>\n\n{class}, go see what it is that the high executor wants.\n\nFollow the road east and pass through The Dragon Wastes. You'll find a path leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, will stand before you on the south side of the mountain.", sourceObjective = "Speak with High Executor Wroth at Venomspite in Dragonblight.", completion = "You were sent from Agmar's Hammer? It's about time!\n\nNo, the help is not for me. I simply have no one else to spare, but you'll do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12489] = { id = 12489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Sholazar Basin", description = "So, where did you come from? I don't suppose that fool of an archmage sent you, too?\n\nYou're lucky to be in one piece, <laddie/lass>! They nearly blew you up!\n\nThe jungle here's a darned dangerous place, 'specially with the Venture Company about.\n\n Git you! Go see the boss... he'll sort you out. The camp's at the end of that path to the northwest.\n\nNow, git!", sourceObjective = "Follow the path to the northwest to reach the camp that Monte mentioned.", completion = "Hah! It's not often you run into a complete stranger in the middle of the jungle.\n\nYou one those druid lackeys sent to \"stop me and my evil ways?\" Yeah, good luck with that one!\n\n<Hemet lets out a hearty laugh and pats his gun.>\n\nDidn't think so! You're more than welcome to join us in the hunt, soon as we've dealt with those Venture Company dogs. There'll be plenty to go around.", sourceObjectiveStatus = "unverified-source-field" }
quests[12490] = { id = 12490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veehja's Revenge", description = "We share a common enemy today, {race}!  My people have been wiped out by these Kvaldir... my city has been all but destroyed.  It is time for exacting revenge!\n\nIn return for my help, I'd like you to slay the barbaric monsters that defile Riplash.  You will be well rewarded, {class}.", sourceObjective = "Veehja at the Shrine of Scales wants you to slay 6 Skadir Mariners, 3 Skadir Mistweavers and 2 Skadir Runecasters.", sourceObjectiveStatus = "unverified-source-field" }
quests[12491] = { id = 12491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", sourceObjective = "Give Direbrew's Dire Brew to Ipfelkofer Ironkeg at the Brewfest camp near Ironforge.", progress = "{name}, your face has a grim set to it.  Do you have dire news?", completion = "This is the Coren Direbrew's drink?  The brew he wanted more than anything to submit at Brewfest?  Well, officially we can't recognize this submission, but out of respect for a fallen brewer, perhaps I'll have a taste...", sourceObjectiveStatus = "unverified-source-field" }
quests[12492] = { id = 12492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", sourceObjective = "Give Direbrew's Dire Brew to Tapper Swindlekeg at the Brewfest camp near Orgrimmar.", progress = "Hey {name}, your face is all smudged!  Have you been to Blackrock Depths?", completion = "Ah, so Direbrew finally submitted his brew.  What a pity he had to die to do it...\n\nOh, well.  Bottoms up, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12493] = { id = 12493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "PvP Test", description = "Kill me some guys from the other side!  Those guys suck!  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.", sourceObjective = "Kill 10 opponents.", sourceObjectiveStatus = "unverified-source-field" }
quests[12495] = { id = 12495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience With The Dragon Queen", description = "Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen.\n\nTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance.\n\nGo now, {name}!", sourceObjective = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns.", sourceObjectiveStatus = "unverified-source-field" }
quests[12496] = { id = 12496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audience With The Dragon Queen", description = "Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward.\n\nBut before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza.\n\nRide now, {name}! Southeast, to Wyrmrest!", sourceObjective = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns.", sourceObjectiveStatus = "unverified-source-field" }
quests[12497] = { id = 12497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galakrond and the Scourge", description = "Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the armies of undead to work day and night to unearth Galakrond's massive bones. Should they succeed in raising Galakrond, all of your efforts will have been for naught.\n\nWhile I cannot call down the full fury of the Red Dragonflight to assist you in your journey, I will grant you my blessing. Go now and speak with my majordomo, Torastrasza.", sourceObjective = "Speak with Torastrasza at Wyrmrest Temple in Dragonblight.", completion = "The bravery of mortals never fails to astound me. Death affixes its cold stare upon you and in return you rise to challenge its assertion! It is why your kind is so loved... and so hated.\n\nEven though the Red Dragonflight is entrenched in a war with Malygos, there is something that we can do to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[12498] = { id = 12498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Ruby Wings", description = "Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms.\n\nDo this and return to Queen Alexstrasza for a hero's reward!\n\n{name}, beware the rotting storm giants that wander the area!", sourceObjective = "Destroy 30 Wastes Scavengers and recover the Scythe of Antiok. Return to Alexstrasza the Life-Binder at Wyrmrest Temple should you complete this task.", progress = "Destroy the Scourge at Galakrond's Rest before it is too late!", completion = "I knew that you would return, {name}. You have served the Wyrmrest Accord and saved your people from certain death. Let it be known to all and let it be recorded for posterity!", sourceObjectiveStatus = "unverified-source-field" }
quests[12499] = { id = 12499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to Fordragon Hold and notify Highlord Fordragon.", sourceObjective = "Speak with Highlord Bolvar Fordragon at Fordragon Hold and tell him of your victory over the Scourge.", completion = "Know this: all that you have done has led to this moment. Without your efforts, we would have been finished! Now, stand guard as I take to the field and end this!", sourceObjectiveStatus = "unverified-source-field" }
quests[12500] = { id = 12500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to the Kor'kron Vanguard and notify Saurfang the Younger.", sourceObjective = "Speak with Saurfang the Younger at the Kor'kron Vanguard and tell him of your victory over the Scourge.", completion = "My father was right about you, {name}. Everything that he said has come to pass - only one final duty remains unfulfilled. I will now lead the Kor'kron to the front line. The time to end this war is at hand. The Lich King's tyranny ends today!\n\nTake my post now, {name}, and stand guard over our forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[12501] = { id = 12501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", sourceObjective = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", sourceObjectiveStatus = "unverified-source-field" }
quests[12502] = { id = 12502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: High Standards", description = "Listen, {class}. This is the Argent Crusade. Our men will fight to the end and never complain no matter what the conditions.\n\nThat said, we've taken some heavy casualties in this campaign and we've been hitting it hard with little or no sleep for months. That all takes a toll on morale, whether we admit it or not.\n\nIt may not seem like much, but seeing our standard raised over the battlefield is of considerable comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.", sourceObjective = "Captain Brandon wants you to place the Argent Crusade Banner in the Drakkari Pedestals at Drak'Sotra.", completion = "Good work, friend.\n\nAmazing what a little of one's colors do for a battleground.\n\nYou'll want to head on over to Captain Rupert next. He's stationed at the wall, just northeast of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12503] = { id = 12503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Stand", description = "Despite our substantial successes in the lower third of Zul'Drak, we must still face the onslaught of the Scourge. Such is the way in this frigid hell.\n\nThe attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid in reinforcing them.\n\nBelow in the courtyard you'll find no end to the fighting. Dispatch the Scourge there with all the zeal you can muster, {class}.", sourceObjective = "Commander Falstaav has tasked you with the destruction of any 10 Scourge in the courtyard at The Argent Stand.", progress = "Perhaps you could destroy a few more?", completion = "Your assistance in this matter is greatly appreciated. Were it not for your efforts, we would have difficulty in holding the unliving back from our steps.", sourceObjectiveStatus = "unverified-source-field" }
quests[12504] = { id = 12504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Crusade, We Are Leaving!", description = "<The sergeant quickly reads through the orders you've handed him, a frown coming over his face.>\n\nLook, <lad/lass>, I'd love to just up and leave, but take a look out there. All of my people are fighting.\n\nTell you what, you've come this far, you think you're up to doing me a small favor? Head out there and round up my soldiers?\n\nTell 'em that the sergeant orders them to report back immediately. Lend them a hand if you will.", sourceObjective = "Sergeant Stackhammer at the Altar of Sseratus wants you to speak with 10 of his Argent Soldiers and tell them to report back to him.", progress = "I'll need more of them to report back in than that.", completion = "Alright then. We'll collect up the rest and head back to the stand.\n\nIt's a shame that we have to leave so soon. Doesn't quite feel like the job's done here, and quite frankly, I get the feeling that prophet in front of the altar is going to be big trouble!", sourceObjectiveStatus = "unverified-source-field" }
quests[12505] = { id = 12505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Orders for Sergeant Stackhammer", description = "{class}, you're here to help, right? I've got new orders for our forces that are currently deployed at the Drakkari altar to the north.\n\nYou can't miss it. Just head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.", sourceObjective = "Commander Kunz has asked you to deliver the New Deployment Orders to Sergeant Stackhammer at the Altar of Sseratus.", progress = "What's this all about?", completion = "<The dwarf sergeant warily eyes the orders in your hand.>\n\nAre those new orders for me, mister?", sourceObjectiveStatus = "unverified-source-field" }
quests[12506] = { id = 12506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Altar of Sseratus", description = "There's trouble at the altar of the snake god.\n\nThe presence of the Scourge has weakened the land, {race}. This in turn has weakened the wild gods.\n\nWe know that the Drakkari are taking advantage of this to do evil things to the gods.\n\nI need you to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. Sneak around the back and get a look inside of the main altar building.\n\nWhatever you do, avoid the prophet at all costs!", sourceObjective = "Hexxer Ubungo at The Argent Stand has asked you to investigate the main altar building at the Altar of Sseratus.", progress = "What did you see, {race}?", completion = "Dead?\n\n<The hexxer's spirit is visibly lowered at the news you bring.>\n\nThey've killed Sseratus and drunk deeply of his mojo; the prophet especially!\n\nWe must figure out a way to put an end to him before he drinks too much more!", sourceObjectiveStatus = "unverified-source-field" }
quests[12507] = { id = 12507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Mojo", description = "This bottle of strange mojo may be the key to what is truly going on here.\n\nThe Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a look at it.", sourceObjective = "Deliver the Strange Mojo to Hexxer Ubungo at The Argent Stand.", progress = "What's that you have there?", completion = "That's the mojo of the wild gods, {class}!\n\nThis is not good!", sourceObjectiveStatus = "unverified-source-field" }
quests[12508] = { id = 12508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mopping Up", description = "I couldn't help but overhear what you were talking to the sergeant about. That doesn't change the fact that we still have a job to do here.\n\nWhile you're out there, do you think you could help us to put some of those followers of Sseratus out of their misery?", sourceObjective = "Corporal Maga at the Altar of Sseratus wants you to kill any combination of 10 Champions of Sseratus, Priests of Sseratus, or Drakkari Snake Handlers.", completion = "Thanks, {class}. I'd have hated to leave without accomplishing what we came out here for in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[12509] = { id = 12509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Intestinal Fortitude", description = "Finally, the patrol arrives!\n\nHere's the situation, {race}. We've lost many of our finest soldiers in this campaign and have had to call upon our recruits to fill in the gaps.\n\nWe've just fought one of our fiercest battles and many of the recruits were simply not prepared to face this enemy. There are more fights ahead, and I need them ready to follow orders.\n\nIf there's one thing I can't stomach, it's cowardice. Perhaps you can help them find the courage to continue.", sourceObjective = "Captain Rupert in Drak'Sotra wants you to restore courage to the cowering Crusade Recruits.", progress = "Well, {class}? How are my recruits?", completion = "Well done, {class}. And not a moment too soon. I've received word that a counter-attack is imminent.\n\nYou should be on your way. The next post is to the northeast, near the coliseum. Captain Grondel should be waiting for you there.", sourceObjectiveStatus = "unverified-source-field" }
quests[12510] = { id = 12510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Elemental Fluids", description = "<The hexxer examines the decanter of mojo.>\n\nI have an idea for how to deal with the prophet of Sseratus. But first, we're going to need some things.\n\nThe Drak'Sotra Fields are directly to the south. Because of the stresses on the land from the Scourge and the deaths of gods, the wall between worlds has weakened and the elementals are flooding in.\n\nWe need the precious fluids of their lords. If you combine three links from the elementals a tether will be made, and one of their lords can be summoned.", sourceObjective = "Hexxer Ubungo at The Argent Stand wants you to acquire 3 Precious Elemental Fluids.", progress = "Do you have the precious fluids?", completion = "Excellent. When combined with the mojo, these fluids will dilute the effectiveness of the mojo without completely eliminating it.\n\nNow, one more thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[12511] = { id = 12511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hills Have Us", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", sourceObjective = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.", completion = "You were almost shot down, eh? Savage monsters - those Horde.\n\nPayback will come for what they've done. You can count on at least that much, {class}.\n\nNow, it's time to put you to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12512] = { id = 12512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No One Behind", description = "Ahh, good. They sent someone.\n\nListen, {race}. We need a hand here. Our forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from is anyone's guess....\n\nThe point is, we need every man we can get here, and some of our best have yet to return from battle.\n\nI need you to enter the ruins now that the fighting has died down and find our wounded, patch them up, and bring them here to me.\n\nScour Drak'Sotra! They couldn't have gone far.", sourceObjective = "Dr. Rogers at Drak'Sotra wants you to find Crusader Lamoof, Crusader Jonathan, and Crusader Josephine. Use the Crusader's Bandage on them, and escort them safely back to him.", progress = "Have you rescued our veterans, {name}?", completion = "Saved them all, did you? Outstanding!\n\nMaybe you'd consider sticking around the post here? We could sure use someone like you....", sourceObjectiveStatus = "unverified-source-field" }
quests[12513] = { id = 12513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", sourceObjective = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! So... it WAS you. I'd thought so. The old scars ached when you drew near, but... so young! You've not changed at all!\n\nWell... so now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've more than earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12514] = { id = 12514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushroom Mixer", description = "Now what we need is something to spike the mojo with. Something that'll make it so that when the prophet drinks it, he'll become less powerful.\n\nDrak'Agal lies to the east. There's a mushroom there that the natives call muddlecap fungus. I think it's exactly what we need.\n\nBring back lots of them. When we mix them into the mojo, the mind of anyone who drinks it will become muddled.", sourceObjective = "Collect 10 Muddlecap Fungus and deliver them to Hexxer Ubungo at The Argent Stand.", progress = "Do you have all of the fungus?\n\nOh, and watch out for the basilisks lurking over there.", completion = "<The hexxer nods his approval.>\n\nHand that fungus over and I'll mix it up with the mojo and elemental lord fluids.", sourceObjectiveStatus = "unverified-source-field" }
quests[12515] = { id = 12515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", sourceObjective = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! But... how did you...?\n\nWell... no matter. So, now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12516] = { id = 12516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Much of a Good Thing", description = "There. I've modified the mojo. Now when the prophet drinks it, not only will he lose some of his power, his mind will also be addled by the effects of the fungus.\n\nAt least that's the theory.\n\nAs for how to get him to drink it, might I suggest you simply throw it at him? No doubt he'll catch and drink it given the arrogance that he's displayed at the altar.\n\nUnless you can kill him, {class}, your Argent Crusade is about to come to a terrible end.", sourceObjective = "Slay the Muddled Prophet of Sseratus and then return to Hexxer Ubungo at The Argent Stand.", progress = "Is it over?\n\nDid the modified mojo work?\n\nDid you deliver vengeance for Sseratus by slaying his prophet?", completion = "Amazing! You've saved your people and the rest of Northrend from his madness.\n\nUnfortunately there's more of this insanity occurring up in the higher tiers of Zul'Drak.", sourceObjectiveStatus = "unverified-source-field" }
quests[12517] = { id = 12517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogues Deck", description = "Now that you have gathered all of the Rogue cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", sourceObjective = "Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to collect a deck of Rogues!   I'm impressed.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12518] = { id = 12518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mages Deck", description = "Now that you have gathered all of the Mage cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", sourceObjective = "Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Mages!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[12519] = { id = 12519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Whatdya Want, a Medal?", description = "Look at me, {race}. Do I look like I have time fer fillin' out reports?\n\nIt be all I can do to keep this post free o' the bloody Scourge, and they want me to mess with paperwork!\n\n<sigh> No sense in complainin'. I need to get the commander some kinda kill count from the last skirmish.\n\nYou wanna be helpful? Go and get me all the medals you can find from the dead trolls around here. That'll hafta be close enough.", sourceObjective = "Captain Grondel outside the Coliseum wants you to gather 7 Drakkari Medallions from the nearby Drakkari Corpses.", progress = "You get those medals for me, {race}?", completion = "Well, now!\n\nYa saved me a fair bit o' work there lad. I'm grateful. I'll be sure ta make mention of ya in me report.\n\nOff with yeh now. Finklestein'll likely be waitin fer ya a bit west o' here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12520] = { id = 12520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Test", description = "No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino. You can prove your worth to the expedition, <lad/lass>, by showing me that you're tough enough to face down those powerful beasts.", sourceObjective = "Kill 15 Shardhorn Rhinos and return to Hemet Nesingwary at the Nesingwary Base Camp.", progress = "Did you master the rhinos, or are you throwing in the towel?", completion = "Well, well, well, it looks like you've survived the rhinos, after all, and in pretty good shape if I do say so myself. But there's more to rhino hunting than just staring down the beast as it charges you and hoping your aim is true. No, you'll need more than that to take on the rhino patriarch that's rumored to dwell in the jungle.", sourceObjectiveStatus = "unverified-source-field" }
quests[12521] = { id = 12521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where in the World is Hemet Nesingwary?", description = "When I heard that the legendary Hemet Nesingwary was setting sail for the Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar,  but it's said to be a lush paradise in the midst of this frozen continent.\n\nHemet has agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he hasn't returned, either. If you'll look into it, I'll send you in my flying machine.", sourceObjective = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!", sourceObjectiveStatus = "unverified-source-field" }
quests[12522] = { id = 12522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need an Engine, Take an Engine", description = "She's ruined... ruined! I told that captain to be careful with such a precious cargo, but would she listen to me? No!\n\nWhen the ship ran aground, it damaged my flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our reports!\n\nThere is a chance, though, that the Venture Company's antics may work in our favor. They shot down another flying machine right about where Monte parachuted into the swamp to the east. Go there and retrieve the engine. It may be our only hope.", sourceObjective = "Weslex Quickwrench at the Nesingwary Base Camp wants you to bring him a Flying Machine Engine.", progress = "Well, were you able to get the engine? I just know that archmage who funded the expedition is getting nervous.", completion = "There... just set it down there. Be careful! If you ruin this one, we're in big trouble. Now, let's see what I can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12523] = { id = 12523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have a Part, Give a Part", description = "Great, now that we've got an engine, we're going to need an assortment of other parts to get her back in flying condition. Don't worry, I know what I'm doing.\n\nA good mechanic can hold his creations together with anything, but we're better off if it doesn't come to that.\n\nAnyway, those Venture Company dullards have plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back here.", sourceObjective = "Bring 7 Venture Co. Spare Parts to Weslex Quickwrench at the Nesingwary Base Camp.", progress = "Did you get those parts?", completion = "With a little work, these should suffice. My poor flying machine might end up looking more like a Venture Company shredder, though. Poor girl will have to wait until we get back to Dalaran to be restored to her rightful form.", sourceObjectiveStatus = "unverified-source-field" }
quests[12524] = { id = 12524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Co. Misadventure", description = "Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights.\n\nWe can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall.\n\nGo to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!", sourceObjective = "Debaar at the Nesingwary Base Camp wants you to kill 15 Venture Company members. You may kill either Venture Co. Ruffians or Venture Co. Excavators.", completion = "That should hamper their operations, but I worry that the foreman will try to bring in more workers. We have to complete the job while we can.", sourceObjectiveStatus = "unverified-source-field" }
quests[12525] = { id = 12525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wipe That Grin Off His Face", description = "We must send Foreman Swindlegrin packing if we're going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn't likely to let you see the foreman without a fight.\n\nThe two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin's Dig.\n\nRemember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, {name}.", sourceObjective = "Kill Foreman Swindlegrin and Meatpie and return to Debaar at the Nesingwary Base Camp.", progress = "Have you dealt with Swindlegrin and his bodyguard?", completion = "What a relief to hear that the Venture Company will trouble us no more. You have my thanks, and that of Hemet for dealing with this problem. A game hunter cannot, in good conscience, lift her weapon against another person.", sourceObjectiveStatus = "unverified-source-field" }
quests[12526] = { id = 12526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Chase", description = "Well, that's settled then. We'll seek out this native sage and have a word with him. He's not likely to volunteer his services, though.\n\nI'm told he keeps a small lean-to near the Bones of Nozronn, just across the river to the south. Seek him out, introduce yourself, and ask what he requires to help us track down this patriarch of the rhinos.", sourceObjective = "Speak to Oracle Soo-rahm at the Bones of Nozronn.", completion = "What brings you to Rahm's shrine?", sourceObjectiveStatus = "unverified-source-field" }
quests[12527] = { id = 12527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluttonous Lurkers", description = "My master, Finklestein, is in the shrine at Heb'Valok to the northwest preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side of the road leading north before the Altar of Sseratus.\n\nThere are basilisks to the east at Drak'Agal.\n\nIf you grab the Zul'Drak rats and throw them at the basilisk, they will become gorged and docile after eating five. Then you'll be able to take their crystals.\n\nKilling the basilisk won't do you any good. That'd just break its crystals!", sourceObjective = "Deliver 5 Basilisk Crystals to Alchemist Finklestein in the shrine at Heb'Valok.", progress = "What's all this?\n\nBy any chance have you seen my no-good apprentice, Pestlepot?\n\nI sent him on an errand quite some time ago and he has yet to return!", completion = "Oh, most excellent! Thank you. The crystals appear to be in fine condition!\n\nI have no doubt that Pestlepot put you up to doing his chores for him. Nevertheless, your assistance in this matter is greatly appreciated!", sourceObjectiveStatus = "unverified-source-field" }
quests[12528] = { id = 12528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Along", description = "My kill! You take my kill!\n\n<Gekgek taunts you with his spear.>\n\nYou dumb, {race}. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for Frenzyheart.\n\nYou go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you the new slave.\n\nGo, {race}! Go or I taunt you a second time!\n\n<Gekgek waves his spear around menacingly.>", sourceObjective = "Report to High-Shaman Rakjak at Frenzyheart Hill as the new \"slave.\"", completion = "You the new slave?\n\nGood. We running out.", sourceObjectiveStatus = "unverified-source-field" }
quests[12529] = { id = 12529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ape Hunter's Slave", description = "You think you so great hunter, eh? You no Frenzyheart, you not know of hunt.\n\nGoregek is great ape hunter. He slay so many ape you can't count on claws.\n\nYou go with Goregek and hunt hardknuckles to east. You the slave, {race}. You do what Goregek tell you.", sourceObjective = "Kill 8 Hardknuckle Foragers and 6 Hardknuckle Chargers for High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", progress = "You still alive! Hardknuckles not eat you yet?\n\nMaybe they eat you later.", completion = "Goregek show silly {race} slave how it done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12530] = { id = 12530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormenting the Softknuckles", description = "Slave thing!\n\nRakjak want me to babysit you while I kill hardknuckles. I feeling generous today, so I let you kill some too, but don't get in Goregek's way!\n\nRakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come yelling!\n\n<Goregek rubs his hands together gleefully.>", sourceObjective = "Goregek has given you a Softknuckle Poker for use on Softknuckles to draw the Hardknuckle Matriarch out of hiding. Slay the Hardknuckle Matriarch and report her death to High-Shaman Rajak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", progress = "What you want, slave?", completion = "Goregek take you to kill big mom of hardknuckles, eh? You lucky!\n\nDumb softknuckles squeal good!\n\n<Rakjak squeals loudly and breaks out laughing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12531] = { id = 12531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underground Menace", description = "Lion killer, chicken chaser, new Frenzyheart slave...\n\nI know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you.\n\nUnder sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness.\n\nHope Dajik teaching you good so Serfex be easy stuff.", sourceObjective = "Locate Serfex under the sands of the southern river, slay him, and bring his claw to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "I not ask for you, {race}. What you want?", completion = "You kill Serfex? I bet you follow mighty wolvar that kill Serfex and take claw.\n\nMy claw now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12532] = { id = 12532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flown the Coop!", description = "Dumb Goregek stumble into chicken house and let all the chickens go!\n\nThey all around hill - go get chickens back!\n\n<Elder Harkek shoos you away.>", sourceObjective = "Capture 12 Chicken Escapees for Elder Harkek.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "You catch chickens?", completion = "Good! I was worried about foodstuffs. I already pretty hungry.\n\nThank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12533] = { id = 12533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wasp Hunter's Apprentice", description = "Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make you into real hunter.\n\nDajik hunts giant wasp things better than all wolvar. Go with Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.", sourceObjective = "Kill 6 Sapphire Hive Wasps and 9 Sapphire Hive Drones for High-Shaman Rakjak in Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "You learn the hunt?", completion = "We kill many many wasps.\n\nRakjak don't think they run out.", sourceObjectiveStatus = "unverified-source-field" }
quests[12534] = { id = 12534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sapphire Queen", description = "Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on other hand not fear the Frenzyheart... they even kill some of our hunters.\n\nI know Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that.", sourceObjective = "Bring the Stinger of the Sapphire Queen to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "You smell like wasp things.", completion = "You killed queen wasp! You stronger than Rakjak thought.\n\nMaybe wasps go away now and stop attacking Frenzyheart hunters.", sourceObjectiveStatus = "unverified-source-field" }
quests[12535] = { id = 12535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischief in the Making", description = "You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you ready for something more important.\n\nBefore Rakjak send you on important mission, you need gather things for Rakjak. All along river to south are blue crystals. Rakjak need lots of blue crystals.\n\nYou go get crystals now.", sourceObjective = "High-Shaman Rakjak at Frenzyheart Hill wants 8 Skyreach Crystal Clusters.", progress = "Almost ready for long journey. Gekgek come back with crocolisk just moment ago.", completion = "Good {race}! Okay, all ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[12536] = { id = 12536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Ride", description = "Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly things near swamps that try to steal all stuff they can find.\n\nZepik going on long trek to break big-tongue shrine and try to scare them away. We no want big-tongues in this land anymore.\n\nThere a crocolisk chained on northeast side of hill, next to tree - go with Zepik and do what Zepik tell you.", sourceObjective = "Ride the captive crocolisk to Mistwhisper Refuge and then speak to Zepik for further instructions.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", progress = "They tell Zepik you good hunter for not being Frenzyheart.", completion = "We here! Must work fast.\n\nWatch out for big-tongues.", sourceObjectiveStatus = "unverified-source-field" }
quests[12537] = { id = 12537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Definitely Strikes Twice", description = "Okay, the crystal things...\n\nThe big-tongues use the crystals to power their rain shrines. Zepik not know quite how it works, but Zepik does know that if they use wrong crystals, the clouds and the rain go crazy!\n\nZepik tried to sneak in at one of their other rain shrines, but it not go so well. It sure to go much better with two!\n\nTake crystals, place at big stone pillar shrine thing, then smash them to release power. Zepik not sure what will happen, so might want to step back after.", sourceObjective = "Zepik wants you to smash the Skyreach Crystal Clusters in front of the Mistwhisper weather shrine.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", progress = "Zepik think this go much better with partner. You strong for not Frenzyheart.", completion = "It work so good!\n\nYou see lightning smash that oracle guy? So good!\n\n<Zepik rubs his hands together and chuckles maniacally.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12538] = { id = 12538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mist Isn't Listening", description = "Gorillas and wasps are boring! Big-tongues the only thing fun to hunt.\n\nWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing.\n\n<Zepik nods to himself confidently.>", sourceObjective = "Zepik wants you to kill 12 Mistwhisper Gorlocs.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", progress = "We best hunters of basin!", completion = "I stab those big-tongues good.\n\nYou did okay I guess.\n\nNo, I just kidding! You good hunter. I glad to hunt with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12539] = { id = 12539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoofing It", description = "Okay, we done! Time to go back. No crocolisk to ride this time though.\n\nIf we go east and stay near ridge, it should lead all the way back near hill.\n\nNeed to be careful not to go far below ridge though or we might go right into big-tongue tree village thing. Zepik not think they like us right now.", sourceObjective = "Find your way back to Frenzyheart Hill and speak to High-Shaman Rakjak.", completion = "Blown up by lightning?\n\n<Rakjak breaks out laughing for a moment.>\n\nYou good hunter. Rakjak like you. Maybe one day you can be honorary Frenzyheart!\n\nOnly maybe though!", sourceObjectiveStatus = "unverified-source-field" }
quests[12540] = { id = 12540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Following Orders", description = "Okay <guy/lady>, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north.\n\nNot bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things.\n\nGo you and bring me big-tongue prize thing.", sourceObjective = "Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill.", completion = "No kill me please! We was just looking for fish. We not want to die.", sourceObjectiveStatus = "unverified-source-field" }
quests[12541] = { id = 12541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", sourceObjective = "Alchemist Finklestein at Heb'Valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", progress = "You see, {name}, there is far more to true alchemy than mixing a few ingredients....", completion = "You've done it!\n\nThe intelligence gathered from that troll will undoubtedly be of great value. I'll be certain to make mention of your efforts in my report to the commander.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12542] = { id = 12542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call Of The Crusade", description = "{class}! The Argent Crusade is looking for able bodied soldiers that are willing to set aside their differences and join forces to battle the forces of the Lich King. Will you take up our cause?\n\nShould you be interested, venture north to Light's Trust and speak with Crusader Valus.\n\nYou will find Light's Trust amidst the ruins of the sacked troll city of Jintha'kalar - bordering Zul'Drak.\n\nFarewell.", sourceObjective = "Report to Crusader Valus at Light's Trust in Dragonblight.", completion = "Mere footsteps from here lies the Drakkari empire.\n\n<Valus points east.>\n\nFor thousands of years the Drakkari remained isolated, preferring to keep within the boundaries of their sprawling temple cities and ziggurats. It was surprising then, to come upon this wreckage. Further up, beyond the foreboding stairs leading into Zul'Drak, Drak'Tharon Keep lies in ruin. The entire first tier of Zul'Drak, destroyed...\n\nWhy has the Scourge waited until now to attack?", sourceObjectiveStatus = "unverified-source-field" }
quests[12543] = { id = 12543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offering for Soo-rahm", description = "We not know you, stranger, but we know you want something.\n\nWe will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle's necklace.\n\nGo to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.", sourceObjective = "Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn.", progress = "We must know -- do you bring fangs?", completion = "<The oracle inspects the fangs.>\n\nWe approve! Bones of Nozronn will speak to {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12544] = { id = 12544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bones of Nozronn", description = "Bones of Nozronn, Oracle Soo-rahm sends {name} to you!\n\nWe have prepared incense for you. Light it and place it near Nozronn's head and you will hear his voice.\n\n<Confused, you tell Soo-rahm that you haven't even told him your question.>\n\nTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart's question.\n\nGo. Nozronn not wait long.", sourceObjective = "Use Soo-rahm's Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary's Base Camp with the information you learned.", progress = "Well, have you consulted the native oracle?", completion = "<Hemet listens as you describe what you learned.>\n\nWay to go, lad. No dead rhino tells Hemet Nesingwary where and what he can hunt. We'll show that heap o' bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[12545] = { id = 12545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing Of Jintha'kalar", description = "We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King.\n\nAll are now lost to the Light. All must be purged.\n\n<Valus looks upon you sternly.>\n\nAll.", sourceObjective = "Crusader Valus at Light's Trust in Dragonblight has asked you to slay 15 Jintha'kalar Scourge.", progress = "Leave nothing for the Lich King to resurrect!", completion = "As you can see, the Scourge war machine presses onward, yet the armies of the Horde and the Alliance remain divided, making for easy prey. It is for this reason that we must remain united.\n\n<Valus is lost in contemplation for a moment.>\n\nThe Argent Crusade has use for a man like you. Perhaps you would be interested in joining our cause? To battle and die at the side of the Ashbringer?", sourceObjectiveStatus = "unverified-source-field" }
quests[12546] = { id = 12546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclamation", description = "It is time, {name}.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.\n\nThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.", sourceObjective = "Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian. Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn.\n\nSpeak to the Avatar of Freya in Sholazar Basin when you've completed this task.", progress = "Those who would threaten life... have they been dealt with?", completion = "I am grateful for your help, {name}.  It is my duty to watch over these lands and all life that dwells on them.\n\nThanks to you, that life will continue to thrive while the forces of death wage in the bordering regions.\n\nYour actions will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12547] = { id = 12547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Activation Rune", description = "This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest.\n\nPerhaps you might be able to find the missing rune inside the nearby overlook.", sourceObjective = "Obtain the Omega Rune inside the Shaper's Terrace and bring it to The Etymidian.", progress = "<The rune-shaped slot on The Etymidian's chest appears to glow with faint power.>", completion = "<You hear the rumbling sound of stone grinding as The Etymidian's limbs come to life.>\n\nI am needed somewhere?", sourceObjectiveStatus = "unverified-source-field" }
quests[12548] = { id = 12548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Etymidian", description = "It is time, {name}.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies.\n\nLet us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.", sourceObjective = "Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side.", completion = "<As you read the engravings on this stone colossus, you realize that this is the weapon that Freya spoke of.  This is the Etymidian.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12549] = { id = 12549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Becoming a Predator", description = "If you've hunted with Hemet before, you know that he's tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They're able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter.\n\nIf you seek to prove you're up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.", sourceObjective = "Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp.", progress = "Have you tested your skills against the dreadsabers?", completion = "Well, you've proven yourself a capable hunter, but how are you as a tracker?", sourceObjectiveStatus = "unverified-source-field" }
quests[12550] = { id = 12550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Stalking the Prey", description = "I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven't seen any evidence of this Shango's existence, but my injuries have kept me from venturing outside the camp.\n\nIf you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.", sourceObjective = "Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake.", progress = "How goes the tracking?", completion = "<Buck listens as you recount your findings.>\n\nI think you may have found the proof we need for this Shango. And I think I have an idea as to where we can find him.", sourceObjectiveStatus = "unverified-source-field" }
quests[12551] = { id = 12551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Trial", description = "I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition.\n\nIf you're looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we'll talk again, hunter.", sourceObjective = "Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment.", completion = "Impressive, {class}. Are you certain you're not a member of the expedition?\n\nNo, I'm certain of it. There would've been a crash joke in there somewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[12552] = { id = 12552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Necromagi", description = "When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within.\n\nNow they're raising our men from the dead and using them against us!\n\nThis will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?", sourceObjective = "Sergeant Moonshard at Drak'Sotra has asked you to destroy 8 Hath'ar Necromagi.", completion = "It's not enough!\n\n<The sergeant's voice cracks as he mourns the corruption of his fallen comrades.>\n\nWe must do more to show respect for the memories of those men!", sourceObjectiveStatus = "unverified-source-field" }
quests[12553] = { id = 12553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skimmer Spinnerets", description = "Why do I always get the tough tasks to tackle?\n\nThe Scourge at Kolramas have plague sprayers that are getting dangerously close. You don't want to know what's going to happen if they start heading this way!\n\nI've got an idea for how we might bring them down, but first we're going to need something... something from their own creatures.\n\nThe Hath'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.", sourceObjective = "Specialist Cogwheel at Drak'Sotra has asked you to collect 5 Intact Skimmer Spinnerets.", progress = "Those spinnerets have to be intact if I'm going to be able to put them together into a device that you can use.", completion = "Those'll do!\n\nNow we're going to need some raw parts so that I can put the launching device together for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12554] = { id = 12554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malas the Corrupter", description = "{name}, head back down there!\n\nYou'll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis.\n\nKill him and bring me his head!", sourceObjective = "Sergeant Moonshard at Drak'Sotra insists that you return with the Head of the Corrupter.", progress = "I look forward to mounting his head on a pike. Let's see him come back from that!", completion = "You're the hero of the hour, {name}.\n\n\n\nYou deserve our deepest respect, and something more I think.", sourceObjectiveStatus = "unverified-source-field" }
quests[12555] = { id = 12555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tangled Skein", description = "There! One tangled skein thrower ready and waiting for you to take those plague sprayers down.\n\nYou just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas.\n\nKind of poetic. I like that!", sourceObjective = "Specialist Cogwheel at Drak'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.", progress = "You sure you brought down enough of those things? Do I look like I want the plague?!", completion = "Yay! You're the best, {name}!\n\nI wasn't looking forward to being sprayed with Scourge stuff, that's for sure! I guess it's going to be hard for those stupid nerubians to spread their evil now!\n\nHow about I give you a little something for saving my skin?", sourceObjectiveStatus = "unverified-source-field" }
quests[12556] = { id = 12556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhino Mastery: The Kill", description = "Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, {name}? For all the spirit's blustering, I'm certain it was telling the truth about the beast's strength.\n\nWhen you're ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.", sourceObjective = "Bring Farunn's Horn to Hemet Nesingwary at the Nesingwary Base Camp.", progress = "Did you kill the beast?", completion = "<Hemet examines the horn.>\n\nAn astounding trophy from an amazing animal! {name}, I've been hearing rumors of even bigger, more ferocious game in the northern reaches of the basin and I'd like you to help us track it down.", sourceObjectiveStatus = "unverified-source-field" }
quests[12557] = { id = 12557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lab Work", description = "I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship.\n\nA worthy aspiration...\n\nShould I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply.\n\nTake your time, {class}. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus.\n\nSucceed, and I'll know to take your request seriously.", sourceObjective = "Alchemist Finklestein at Heb'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory.", progress = "Have you become accustomed to my laboratory, {class}?", completion = "Yes, yes, that's a good start.\n\nShould I call upon you to help me with an actual recipe, you'll need to locate ingredients in a timely manner.\n\nKeep that in mind, {class}.\n\nFarewell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12558] = { id = 12558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadsaber Mastery: Ready to Pounce", description = "Shango awaits, {name}. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.\n\nHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.", sourceObjective = "Bring Shango's Pelt to Buck Cantwell at the Nesingwary Base Camp.", progress = "Have you taken on Shango?", completion = "What an exquisite pelt from such a noble animal! It heartens me to see that the rumors about Shango were indeed true, {name}. Your pursuit of the creature has been flawless. You are a true huntsman.", sourceObjectiveStatus = "unverified-source-field" }
quests[12559] = { id = 12559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Waygate - The Makers' Perch", description = "It is time then.  Let us activate the waygate.\n\nYou will find the first switch inside the Makers' Perch in the western edge of the basin.\n\nBeware, {name}.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.", sourceObjective = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Makers' Perch and use the Activation Switch Gamma.", progress = "You're back, little one.  I was beginning to worry about your well-being.", completion = "We're halfway there, {name}.  One more switch needs to be activated before we can retrieve the Etymidian.", sourceObjectiveStatus = "unverified-source-field" }
quests[12560] = { id = 12560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Plan", description = "The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we'll need to construct a convincing camouflage for you. We'll use plants that grow in the sandy soil of the riverbanks and lake beaches.\n\nThe sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River's Heart, the large lake beyond the mangal to the east.", sourceObjective = "Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp.", progress = "Did you bring all the ferns we'll need?", completion = "<Debaar accepts the sandfern fronds from you and starts bending them around your body.>\n\nYes, this should work. Stand still! We'll make a bush of you yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12561] = { id = 12561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Issue of Trust", description = "This should never have happened.  The forces of undeath storm the very cradle of life!\n\nIf you're not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.", sourceObjective = "Obtain Freya's trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.", progress = "Do not waste my time, mortal.  The titans' creations must be defended!", completion = "Very well, {race}.  I am satisfied that you're not one of the Lich King's minions... perhaps there is something you can do for us after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12562] = { id = 12562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drakkari Do Not Need Water Elementals!", description = "Intelligence reports that ever since those water elementals appeared in the Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul'Drak to take control of them.\n\nI cannot stress enough, <sir/ma'am>, how dangerous that could prove. We do not want them to have water elementals at their disposal.\n\nThe commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you're ready.", sourceObjective = "Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders.", completion = "Excellent work, sir!\n\nI'll see to it that the commander is apprised of your mission results.", sourceObjectiveStatus = "unverified-source-field" }
quests[12563] = { id = 12563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", sourceObjective = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", sourceObjectiveStatus = "unverified-source-field" }
quests[12564] = { id = 12564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", sourceObjective = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", progress = "Have you collected the water-poppies, {name}?", completion = "Fine specimens, {name}.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12565] = { id = 12565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Abwa", description = "I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, {race}. I would like to help with your efforts.\n\nThe Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse.\n\nIf you were to make offerings to the gods, they would show their appreciation in return.\n\nZim'Abwa's statue is just to the southwest. Zim'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul'Drak.", sourceObjective = "Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim'Abwa.", progress = "<Zim'Abwa stares inscrutably to the north and the south.>", completion = "<If Zim'Abwa could move his face, Zim'Abwa would make a vicious grin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12566] = { id = 12566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Camp Winterhoof", description = "I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof to seek out allies in the fight against the vrykul. They mass to the west and south of our village, and though we slay 10 of them for every one of our dead, we cannot hold.\n\nApothecary Scyllis has promised to send brave {class}s northwest to our aid. Will you help my people fend off the vrykul assaults?\n\nFollow the road far to the northwest, across the river, and into the foothills of the mountains to reach Camp Winterhoof.", sourceObjective = "Speak with Chieftain Ashtotem at Camp Winterhoof.", completion = "So, Nanik did find help then? Tell me, {name}, how is it you made it here without him? None know this land better than the Taunka.", sourceObjectiveStatus = "unverified-source-field" }
quests[12567] = { id = 12567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Abwa", progress = "<Zim'Abwa's stony visage pierces your soul.\n\nZim'Abwa is pleased, but wants you to show more appreciation and respect by giving him more Drakkari offerings.\n\nHe will reward you in kind.>", completion = "<You sense Zim'Abwa's approval. Somehow you know that Zim'Abwa wants more tribute!>" }
quests[12568] = { id = 12568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Done to Death", description = "Trust me, {race}. I know....\n\nThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.\n\nPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.", sourceObjective = "Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra.", completion = "Thank you, {name}.\n\nIt's not the most glorious job on the battlefield, but it must be done. I'll make note of your service in my report.\n\nCaptain Grondel is likely waiting for you to the northeast, just outside the amphitheater.", sourceObjectiveStatus = "unverified-source-field" }
quests[12569] = { id = 12569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Mastery: The Ambush", description = "The largest crocolisk in the basin, known around here as \"Bushwhacker\" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp.\n\nI want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.", sourceObjective = "Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.", progress = "Did our plan work?", completion = "<Debaar listens as you describe the failure of the disguise.>\n\nWhat do you mean, our plan didn't work as intended?\n\nWell, you did manage to get the kill, to your credit. Look at the size of this jaw! Hemet will be proud of our efforts. This crocolisk was truly a monster.", sourceObjectiveStatus = "unverified-source-field" }
quests[12570] = { id = 12570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortunate Misunderstandings", description = "I sorry! I not mean to get you in trouble!\n\n<The injured oracle stares at you blankly for a long while.>\n\nYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.\n\nLet me know when you ready to go, okay?", sourceObjective = "Escort the Injured Rainspeaker Oracle to Rainspeaker Canopy and speak to High-Oracle Soo-say.", progress = "Who you? You stink of puppy-men.", completion = "You help us? You welcome then, dryskin.", sourceObjectiveStatus = "unverified-source-field" }
quests[12571] = { id = 12571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make the Bad Snake Go Away", description = "We were here long before the puppy-men came. This is very sacred place - we will not leave.\n\nYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.\n\nThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.", sourceObjective = "High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "<High-Oracle Soo-say seems to stare right through you.>", completion = "Snake gone?\n\nGood {race}. We thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12572] = { id = 12572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gods like Shiny Things", description = "Soo-say said we go with you. You be nice, okay?\n\nOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt!\n\nLet's go! Let's go! More offerings for shrine!", sourceObjective = "Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Hello dryskin. You get along with Lafoo good?", completion = "Shinies for the Great Rain Stone! Good! Good!\n\nWe offer these right away. Lafoo thought of this, yes? He a very smart Rainspeaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[12573] = { id = 12573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Peace", description = "We have great idea. You were friends with puppy-men, they maybe listen to you.\n\nWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.\n\nYou good {race}. We trust you do this right.", sourceObjective = "High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Puppy-men play nice now?", completion = "So mean! We only be nice and they only be mean.\n\nThey keep messing with great stones... maybe they not know great stones are sacred.", sourceObjectiveStatus = "unverified-source-field" }
quests[12574] = { id = 12574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back So Soon?", description = "<High-Oracle Soo-say stares at your forehead for a while before speaking.>\n\nSoo-gan ask for help. We think they might have been attacked by puppy-men again.\n\nWe sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that.\n\n<High-Oracle Soo-say goes back to staring at your forehead as you leave.>", sourceObjective = "Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", completion = "We think we seen you before. You visit Mistwhisper village sometime already?\n\nSoo-say said you good. Soo-say smart, so we trust you too.\n\n<Mistcaller Soo-gan offers an awkwardly large smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12575] = { id = 12575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Mistwhisper Treasure", description = "So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.\n\nAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!\n\nOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!", sourceObjective = "Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Dumb puppy-thieves.", completion = "You did it! You strong and nice! Good friend of Mistwhispers!\n\n<Mistcaller Soo-gan lets loose a big toothy grin.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12576] = { id = 12576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forced Hand", description = "We try to be nice to puppy-men ever since they came, but they nothing but mean.\n\nWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.\n\nWe wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!", sourceObjective = "Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "They always want fight! We no want fight, but we need to protect sacred stuffs.", completion = "You squash good. Thank you for help.", sourceObjectiveStatus = "unverified-source-field" }
quests[12577] = { id = 12577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Time!", description = "You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now.\n\nYou go back to Rainspeaker Canopy and tell Soo-say you done good.", sourceObjective = "Return to Rainspeaker Canopy.", completion = "You back so soon!\n\nWent good then, yeah?", sourceObjectiveStatus = "unverified-source-field" }
quests[12578] = { id = 12578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Angry Gorloc", description = "I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.\n\nYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.", sourceObjective = "Travel to Mosswalker Village and speak to Moodle once you've arrived.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Soo-say fumbles a bit, but he's not dumb. I do think he's been far too forgiving though... the puppy-men are not going to stop or leave us alone. The only way to stop them is to kill them... there is no \"peace.\"\n\n<Moodle puffs up his chest and points to himself.>\n\nThat I am good at.", completion = "Before you say anything, do not assume me as foolish as most of the Oracles you've met. I've been into the world a bit, I've learned your language, and I'm not easily duped.\n\nI knew the Mosswalkers were dead before we ever came, though I didn't know that the undead were behind it.\n\nThey are not supposed to be able to enter this land... the destruction of the Lifeblood Pillar must have allowed them in somehow. We must see to it that they leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[12579] = { id = 12579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifeblood of the Mosswalker Shrine", description = "I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.\n\nNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.\n\nThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.", sourceObjective = "Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "The Mosswalkers were good people... they did not deserve this.", completion = "We might be too late for the shards to make a difference, but our options are somewhat limited.", sourceObjectiveStatus = "unverified-source-field" }
quests[12580] = { id = 12580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosswalker Savior", description = "There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.\n\nLet's find some revenge for this slaughter and see if there are any to be saved in the process.", sourceObjective = "Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "I wish I had known how key the pillars and the stones were much earlier... perhaps I could have prevented this.", completion = "I'm very glad there were some to be saved... with luck, they'll make it back to Rainspeaker Canopy safely.", sourceObjectiveStatus = "unverified-source-field" }
quests[12581] = { id = 12581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Burden", description = "Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done.\n\nWe need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard.\n\nThe corpses being dragged there would suggest as much anyway.\n\nI'll place the shards and bring the news to Soo-say... I'll leave the rest up to you.", sourceObjective = "Kill Artruis the Heartless.\n\nMoodle will not be able to accompany you on this task.", progress = "<The phylactery rests ominously on the ground next to Artruis's dead form.>", completion = "<Inside Artruis's Phylactery you see what seems like an endless void... and you think you hear screaming in the distance from somewhere inside.>\n\n<As you're about to leave, you see an object floating in the void, just barely in reach.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12582] = { id = 12582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzyheart Champion", sourceObjective = "I know you weren't traitor thing like others said. We hunt together... I know you better than all of them. Thank you for saving me.\n\nMay sound funny... I not a big fan of big-tongues... but even I feel little bad for big-tongue dying like that though...they fight good enough they deserve fair fight.\n\nYou want to be friends with Frenzyheart again? I think I can convince them that you save me and got the big-tongues good. I no want you to make me look dumb though, so you sure no more big-tongues for you?", sourceObjectiveStatus = "unverified-source-field" }
quests[12583] = { id = 12583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crashed Sprayer", description = "I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us.\n\nWhy don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!", sourceObjective = "Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts.", progress = "Do you have the parts? Huh? Do you?", completion = "<The specialist steps back a bit when presented with the parts.>\n\nEw, those things are totally gross!\n\nOkay, okay, hand them over and I'll see what I can do. I probably should have had you take them to a priest first for purification.", sourceObjectiveStatus = "unverified-source-field" }
quests[12584] = { id = 12584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pure Evil", description = "We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.\n\nMy scouts tell me that much of the saronite is strewn about within the innards of that thing.\n\nEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.\n\nI want you to head in there and see if you can collect enough for them.", sourceObjective = "Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.", progress = "Yes, {class}?\n\nPlease tell me that you have the saronite that we requested Captain Rupert to acquire?", completion = "Can you not feel the pure evil of the stuff?\n\nWe must use the expertise and magics at our disposal, combined with the power of the Holy Light, to pierce the veil of iniquity surrounding this tainted ore. We must determine its origins.\n\nQuickly, hand the saronite to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[12585] = { id = 12585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", sourceObjective = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' Cap'n Arnath due west o' here, just over the rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12586] = { id = 12586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", sourceObjective = "Talk to <x> at <x>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12587] = { id = 12587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", sourceObjective = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok.", completion = "Well, {name}, at least you've made it back in one piece. I suppose that's worth something....", sourceObjectiveStatus = "unverified-source-field" }
quests[12588] = { id = 12588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Can You Dig It?", description = "One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.\n\nMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.\n\nTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.", sourceObjective = "Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.", completion = "Thank you for looking into this for me, {name}. I'll make mention of your service in my report.\n\nYou'll likely want to visit Captain Rupert next. He's stationed at the wall due east of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12589] = { id = 12589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, What Kick?", description = "So you think you can shoot?\n\nWell, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at.\n\nNow, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!", sourceObjective = "Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan.", progress = "Satisfied with the results?", completion = "You're not a bad shot, but you'll get better with practice. How would you like to make a little wager?", sourceObjectiveStatus = "unverified-source-field" }
quests[12591] = { id = 12591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two nethurbian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", sourceObjective = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12592] = { id = 12592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Hunter's Challenge", description = "So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt.\n\nHow'd you like to have a bit of a competition, just me and you?\n\nHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!", sourceObjective = "Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.", progress = "Care to count 'em up?", completion = "So, you've come to concede already?\n\n<Drostan's jaw drops as you tell him you've already made all your kills.>\n\nNo way! How in Azeroth did you do that? I just made my 58th. So close!\n\nBut fair's fair. I underestimated you, {name}, but you've earned this victory fair and square.", sourceObjectiveStatus = "unverified-source-field" }
quests[12593] = { id = 12593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service Of The Lich King", description = "All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge.\n\nGaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance.\n\nYou will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.", sourceObjective = "Report to Instructor Razuvious in the Heart of Acherus.", completion = "You have heard the call of the Lich King, {class}. Now is the time to answer your master.", sourceObjectiveStatus = "unverified-source-field" }
quests[12594] = { id = 12594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Patrol: Couldn't Care Less", description = "Of all the posts, they throw me in this one.\n\nThe place is flooded with putrid, stagnant water and now it's host to sewage elementals!\n\nI don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?\n\nGet out there, {class}, and don't come back 'til you've cleared your share of 'em off of my battlefield!", sourceObjective = "Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal.", progress = "You clear the area of bog beasts yet, {class}?", completion = "You sure about that, {race}?\n\nSeems to me like there are more of them things out there now than when you started!", sourceObjectiveStatus = "unverified-source-field" }
quests[12595] = { id = 12595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bigger Game", description = "Well, {name}, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.\n\nDorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.", sourceObjective = "Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin.", completion = "So old Hemet didn't forget about me, after all. I suppose he's going to want to participate in the hunt once we've done all the hard work. Don't worry, there are plenty of drakes to go around. Hemet will get his wish.", sourceObjectiveStatus = "unverified-source-field" }
quests[12596] = { id = 12596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pa'Troll", description = "Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.\n\nDon't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one.\n\nHere, you report to me and you follow my orders to the letter. Understood?!\n\nFirst, you're going to get familiar with my men and the region we're charged with clearing.\n\nReport to each of them and do as they ask. Return to me when your patrol is done.", sourceObjective = "Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here.\n\nCaptain Grondel is posted in Drak'Agal, due east.\n\nAlchemist Finklestein is posted in Heb'Valok, to the north.", completion = "It's about time you got your carcass back here! Thought we'd lost ya to the Scourge - not that it would've been a great loss....\n\nIf you're going to continue to serve the Crusade, you'd best make a more impressive showing.\n\nTake note, {race}! Your future patrols will be rewarded based on your timeliness.\n\nDismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12597] = { id = 12597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", sourceObjective = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", progress = "Have you collected the water-poppies, {name}?", completion = "Fine specimens, {name}.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[12598] = { id = 12598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two Nerubian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", sourceObjective = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.", progress = "Have you sealed the nerubian tunnels, {name}?", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12599] = { id = 12599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", sourceObjective = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, {race}?", completion = "Mighty kind of ya, {name}. Mighty kind indeed.\n\nNow you'll be findin' ol' Finklestein due west o' here, just over the rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12601] = { id = 12601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", sourceObjective = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", sourceObjectiveStatus = "unverified-source-field" }
quests[12602] = { id = 12602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!", sourceObjective = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", sourceObjectiveStatus = "unverified-source-field" }
quests[12603] = { id = 12603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharpening Your Talons", description = "The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.\n\nStill, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.", sourceObjective = "Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost.", progress = "Have you tested your skills?", completion = "I can hear the confidence in your words. Good, the experience will come in handy when we face the queen of the drakes.", sourceObjectiveStatus = "unverified-source-field" }
quests[12604] = { id = 12604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Congratulations!", sourceObjective = "You made excellent time on that patrol. It appears that you may be of use to us after all.\n\nAs promised, here's a little something extra for your efforts.\n\nKeep up the good work, {name}.\n\nDismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12605] = { id = 12605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Bait", description = "We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project.\n\n<Dorian glances over at Zootfizzle.>\n\nBut don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.", sourceObjective = "Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost.", progress = "Have you secured the bait we'll need to get the broodmother's attention?", completion = "Ah, well done. Plenty of little hatchlings for Zootfizzle over there!", sourceObjectiveStatus = "unverified-source-field" }
quests[12606] = { id = 12606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cocooned!", description = "Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.\n\nWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.\n\nFree them, {class}, while you still can!", sourceObjective = "Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen.", progress = "Have you freed our soldiers from the clutches of the nerubians?", completion = "These nerubians have taken a heavy toll, {class}.\n\nNevertheless, I am grateful for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12607] = { id = 12607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mammoth Undertaking", description = "Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.\n\nThe area around the camp is full of them. Just take this bridle and slip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.", sourceObjective = "Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost.", progress = "Everything taken care of?", completion = "Perfect! Now, all we need to do is get Hemet a stepladder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12608] = { id = 12608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultist Incursion", description = "<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.>\n\n<You'd best warn her about the Lich King's living agents within Sholazar Basin.>", sourceObjective = "Speak to the Avatar of Freya at the Rainspeaker Rapids.", completion = "The living... willingly serve the Lich King?\n\nAll this time I've been searching for the wrong enemy, {race}.  Let us make haste and uproot these cultists from these lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[12609] = { id = 12609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking the Shelves", description = "Listen, {class}. I realize that it's a lot to ask....\n\nFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon.\n\nI'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance.\n\nAs you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.", sourceObjective = "Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.", progress = "Have you collected the reagents I need, {class}?", completion = "These look to be excellent samples, {name}.\n\nThank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12610] = { id = 12610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clipping Their Wings", description = "Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes.\n\nI'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here.\n\nHelp me, {race}. Collect some bat wings for me so that I might get back to the real action sooner.", sourceObjective = "Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.", progress = "Have you finished collecting those bat wings for Finklestein?", completion = "Excellent work, {name}.\n\nI thank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12611] = { id = 12611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returned Sevenfold", description = "The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.\n\nThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.", sourceObjective = "The Avatar of Freya wants you to defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.", progress = "Is it done, {name}?", completion = "You continue to prove yourself, {name}.  Perhaps I was too quick to judge you.\n\nI had assumed you were here with the poachers who were recently stranded in my lands, but perhaps you're ready to put that behind you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12612] = { id = 12612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Pillar", description = "The titans shaped entire life forms here, fostering their unfettered growth.\n\nThe five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed.\n\nGo to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.", sourceObjective = "Travel to the Lifeblood Pillar and look for clues to its destruction.", completion = "<The corpse is badly burnt.  There appear to be the remains of several powder kegs in the vicinity.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12613] = { id = 12613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Waygate - The Makers' Overlook", description = "We cannot stop now, {race}.  You've triggered the first switch, but one remains.\n\nThe titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains.\n\nPull the activation switch theta inside the overlook and the waygate will open.", sourceObjective = "The Avatar of Freya wants you to head to the Makers' Overlook in eastern Sholazar Basin and use the Activation Switch Theta.", progress = "Is it done, {name}?", completion = "The waygate is active, {name}.  It is time!", sourceObjectiveStatus = "unverified-source-field" }
quests[12614] = { id = 12614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Post-partum Aggression", description = "Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that.\n\n'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.\n\nShe'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.\n\nShe's on her perch at the northern edge of the Savage Thicket and hungers for revenge.", sourceObjective = "Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.", progress = "Well, you're alive. How did you fare?", completion = "Well, I had a whole speech prepared, but the old man himself has some words he wants to say to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12615] = { id = 12615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Zim'Torga", description = "Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.\n\nWe have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.", sourceObjective = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga.", progress = "<You can feel the eyes of the Mother of Prosperity upon you. She is wondering what a {race} such as yourself is doing standing before her.>", completion = "<Zim'Torga's thoughts pervade your own. She senses the offerings you are about give to her and is pleased.>\n\n<She conveys that you will be appropriately rewarded.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12616] = { id = 12616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chamber of Secrets", description = "Excellent, an experienced adventurer. Precisely what we need.\n\nThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.\n\nGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.", sourceObjective = "The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.", completion = "The information you report is dire indeed if the orders you saw are legitimate. We can only hope that his mission was stopped early enough to prevent the enemy from knowing too much about our strengths.\n\nThank you, {name}. May you remain safe in these dark times.", sourceObjectiveStatus = "unverified-source-field" }
quests[12617] = { id = 12617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterminate the Intruders", description = "I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.\n\nI never anticipated the Lich King would send willing living servants to do his work.\n\nI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, {name}.  Deliver my wrath to these insolent trespassers.", sourceObjective = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.", progress = "Have you destroyed the trespassers, {name}?", completion = "You speak the truth.  The intruders at the camp were dealt with... but I'm afraid it might have been too late.", sourceObjectiveStatus = "unverified-source-field" }
quests[12618] = { id = 12618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Zim'Torga", progress = "<Zim'Torga looks on impassively. She wonders if you seek her continued blessing by presenting more Drakkari offerings to honor her.>", completion = "<The Mother of Prosperity beams her approval down upon you.>" }
quests[12619] = { id = 12619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emblazoned Runeblade", description = "The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power.\n\nThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.", sourceObjective = "Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.\n\nReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.", progress = "The runeblade is an extension of your being. A {class} cannot battle without a runeblade.", completion = "Well done, {name}. You have successfully created your first runebladed weapon. With it you will sow the seeds of chaos and destruction! In your wake will be a bloodied field of battle, littered with the corpses of all that would dare oppose the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12620] = { id = 12620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lifewarden's Wrath", description = "We were not quick enough, {name}.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.\n\nWe don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.\n\nWe shall show this scum to not trifle with the titans' creations.", sourceObjective = "The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar.", progress = "Have you taken care of the cultists, {name}?", completion = "Impressive.  I wasn't expecting a mere mortal to prove as worthy an ally as you.\n\nI fear our efforts have not been sufficient, however.  The Scourge shows no signs of stopping.", sourceObjectiveStatus = "unverified-source-field" }
quests[12621] = { id = 12621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freya's Pact", description = "The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, {name}.\n\nThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.", sourceObjective = "Listen to what the Avatar of Freya has to say.", progress = "We have little time.  The Scourge is preparing for a final push.", completion = "There is no turning back now.  If you agree to help me, you will do so without hesitation.", sourceObjectiveStatus = "unverified-source-field" }
quests[12622] = { id = 12622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leaders at Jin'Alai", description = "You thinkin' what Ahunae thinkin', mon?\n\nSome of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too!\n\nGo in there and kill those trolls. When you kill enough, their leaders show up.\n\nWhen they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.", sourceObjective = "Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.", progress = "The {class} must be back talkin' to Ahunae because the {class} has all that treasure.", completion = "The scalper thinkin' that you be his kind of {race}!\n\nWhat's these candybars doin' in here? What we do with this, mon?\n\nAhunae say that you can have them back!", sourceObjectiveStatus = "unverified-source-field" }
quests[12623] = { id = 12623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Witch Doctor", description = "We Zandalari could use your help, {name}. We must put an end to what the Drakkari are doing to their gods!\n\nTo the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.\n\nI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.", sourceObjective = "Speak with Witch Doctor Khufu at Zim'Torga.", completion = "Greetings to you, {class}. I am glad to hear that Ubungo found someone that he could trust.\n\nWelcome to Zim'Torga.", sourceObjectiveStatus = "unverified-source-field" }
quests[12624] = { id = 12624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Could Be Anywhere!", description = "When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months!\n\nI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere!\n\nI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!", sourceObjective = "Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.", progress = "The ring, {name}!  Please... tell me you've found it!", completion = "You did it!  You actually found it!\n\nI don't know... I don't know how to thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12625] = { id = 12625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominion Over Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.\n\nThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!\n\nTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.", sourceObjective = "Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12626] = { id = 12626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Company of the Damned", description = "<Corvus salutes.>\n\nOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!\n\n<Corvus rolls up a fleshy piece of vellum.>\n\nOn the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.", sourceObjective = "Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[12627] = { id = 12627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through Jin'Alai", description = "I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts.\n\nIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.\n\nDisturb each of the cauldrons to bring down their ritual that is blocking me.", sourceObjective = "Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.", completion = "Yes, I can already feel the difference. Thank you.\n\nLet us see if we can make contact with the gods now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12628] = { id = 12628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Speak With Har'koa", description = "The gods have spoken, {name}. We now know what you must do.\n\nYou must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.", sourceObjective = "Speak with Har'koa at the Altar of Har'koa.", completion = "Listen closely, little {race}. Time is of the essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[12629] = { id = 12629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can Run, But You Can't Hide", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.", sourceObjective = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought me the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do. Now brace yourself, {class}. This is where it gets good....", sourceObjectiveStatus = "unverified-source-field" }
quests[12630] = { id = 12630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickin' Nass and Takin' Manes", description = "Before you meet Nass, there's something you should know.\n\nHe got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb.\n\nIt's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you.\n\nThere are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.", sourceObjective = "Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.\n\nIf you lose Nass, return to Stefan to recover him.", progress = "How's that boot holding up, {race}?", completion = "You know, you remind me an awful lot of my Nass.\n\nMaybe it's just the nose...", sourceObjectiveStatus = "unverified-source-field" }
quests[12631] = { id = 12631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation, of Sorts...", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", sourceObjective = "Take the Unliving Choker to Stefan at Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12632] = { id = 12632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "But First My Offspring", description = "I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.\n\nBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.\n\nTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.", sourceObjective = "Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.", progress = "There are more of my offspring that you must free from their torment!", completion = "Thank you, {name}. I will never forget what you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12633] = { id = 12633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Calling", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", sourceObjective = "Take the Writhing Choker to Stefan in Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, {name}, that you have been... chosen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12634] = { id = 12634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Make Lemonade, Some Make Liquor", description = "Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition!\n\nWe need to get some booze cooking, and fast!!\n\nThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.", sourceObjective = "Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Did you have luck winning any of that fruit from those darn tall and stingy trees?", completion = "Well, that's a better assortment than I would've expected from this place. Now, for the important question: can we distill it into anything drinkable? We'd better get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[12635] = { id = 12635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Snow Leopard Goddess", description = "I overheard that you are going to see to the well-being of Har'koa. Good luck to you.\n\nI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.\n\nWhat do you say?", sourceObjective = "Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics.", progress = "The Drakkari are so busy destroying themselves, it would be a shame if the historical significance of their empire were to be likewise lost.", completion = "Aw, prime specimens!\n\nYou can see there the divergence from the root symbology. Quite extraordinary.\n\nWhat a pity that the ice trolls are determined to bring about their own demise.\n\nDid you know, for instance, that the Drakkari were exiled from the rest of the troll nations for their extremely violent ways?\n\nIt's true! How did you think trolls ended up in such a harsh climate as this?", sourceObjectiveStatus = "unverified-source-field" }
quests[12636] = { id = 12636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye Of Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! the Lich King has called for you, {name}.\n\nGo now! Suffer well, <brother/sister>...", sourceObjective = "Report to the Lich King in Ebon Hold.", completion = "The time to spill the blood of our enemies approaches. You must first learn what it is that you seek to destroy, before rushing headlong into battle. It is what separates a {class} from a mindless ghoul.\n\nI will grant you sight beyond sight, my champion. You will use the eye of Acherus to steal our enemies' secrets.", sourceObjectiveStatus = "unverified-source-field" }
quests[12637] = { id = 12637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Near Miss", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurance. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", sourceObjective = "Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no coincidence. The creation of such a device is very involved, and the required resources would not be squandered on a random target.\n\nThe simple truth of the matter is this; You're wanted by the Scourge....", sourceObjectiveStatus = "unverified-source-field" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close Call", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurence. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", sourceObjective = "Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.", progress = "Yes, {race}?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no random act. The creation of such a device is very involved. You've somehow caught the attention of the Scourge leadership.\n\nThe question is not how, why, or even who... but what will we do about it?", sourceObjectiveStatus = "unverified-source-field" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Earth", description = "We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.\n\nThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.", sourceObjective = "Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.", progress = "I hope that you've returned with enough. The attacks from the Pools of Jin'Alai have become more desperate after what you did to them.", completion = "Thank you, {class}. Those essences should be enough to fuel my casting for quite some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Rifts", description = "Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already.\n\nWhile you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us!\n\nJust watch out, more of those frozen earth'll show up when you try to seal the rifts.", sourceObjective = "Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts.", completion = "Ahunae hopin' that Dagoda got all of the defenders she wantin'. With those rifts sealed, it's not likely she'll be gettin' any more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Comes From On High", description = "Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.\n\nUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, {name}.\n\nThe Scourge will have this place. The Lich King commands it!", sourceObjective = "The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.\n\nControl the Eye of Acherus by using the Eye of Acherus Control Mechanism.", progress = "Our assault upon the Scarlet Crusade will become legend.", completion = "They prepare for battle - as expected - but there is something else. I sense an old enemy. An enemy that I destroyed long ago...\n\nIt matters not. We will send the full might of the Scourge against them before they have a chance to evacuate their homes and put in place their defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of Rhunok", description = "My feelings tell me that Rhunok doesn't have much time.\n\nI can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune.\n\nHis altar lies to the northwest beyond Drak'Mabwa.", sourceObjective = "Speak with the Spirit of Rhunok at the Altar of Rhunok.", completion = "I am barely hanging on. You must work quickly or all will be lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Lining", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.", sourceObjective = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought the components I asked for, {name}?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do.\n\nNow brace yourself, {class}. This is where it gets good....", sourceObjectiveStatus = "unverified-source-field" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still At It", description = "Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong.\n\nIngredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.", sourceObjective = "Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Well, how did it turn out?", completion = "<Grimbooze gives the cask a shake.>\n\nThere's something in here, but the million gold question is, can you drink it? Don't you go anywhere; you'll be responsible for overseeing the sampling of the product, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taste Test", description = "And now for the moment of truth!\n\n<Grimbooze chuckles.>\n\nI've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle.\n\nInstead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.", sourceObjective = "Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Don't keep me waiting, {name}. What are the results?", completion = "Two out of three drinkers agree, eh? Not bad for a first try. Not bad at all. I suppose I'll have to whip up something else for Tamara by way of apology.\n\nNow... what should we call this creation?", sourceObjectiveStatus = "unverified-source-field" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Prophet, My Enemy", description = "My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa.\n\nMy former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens.\n\nYou must put an end to him and return with my mojo before it is too late.", sourceObjective = "The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.", progress = "Quickly, {race}, do you have my mojo?", completion = "You did it.\n\nBut now there is one other thing that I need you to do.", sourceObjectiveStatus = "unverified-source-field" }
